cy=\"62\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"248\" y=\"66.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <line x1=\"38\" y1=\"46\" x2=\"80\" y2=\"28\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"84\" y=\"28\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"monospace\">origam-avatar-group</text>\n  <line x1=\"80\" y1=\"52\" x2=\"80\" y2=\"32\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"95\" y=\"26\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-family=\"monospace\">__item (×N)</text>\n  <line x1=\"248\" y1=\"52\" x2=\"248\" y2=\"32\" stroke=\"var(--origam-color__action--primary---bgHover, #a855f7)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"263\" y=\"26\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-family=\"monospace\">__rest (+N chip)</text>\n  <text x=\"280\" y=\"162\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">Avatars overlap via negative margin; __rest is always last.</text>\n", "code": "<div class=\"origam-avatar-group origam-avatar-group--horizontal\" role=\"group\">\n  <!-- #avatar slot × N (visible items) -->\n  <origam-avatar class=\"origam-avatar-group__item\" />\n  <origam-avatar class=\"origam-avatar-group__item\" />\n  <origam-avatar class=\"origam-avatar-group__item\" />\n\n  <!-- #rest slot — shown when items.length > max -->\n  <origam-avatar class=\"origam-avatar-group__rest\">\n    <!-- #default slot — renders \"+N\" label -->\n    +2\n  </origam-avatar>\n</div>", "legend": [{"cls": ".origam-avatar-group", "num": 1, "descriptionKey": "components.avatar_group.anatomy.root", "descriptionFallback": "Root element. Renders as an inline-flex container with <code>role=\"group\"</code>. Direction modifier class controls flex-direction."}, {"cls": ".origam-avatar-group__item", "num": 2, "descriptionKey": "components.avatar_group.anatomy.item", "descriptionFallback": "Each visible avatar. Receives a negative margin-inline-start (horizontal) or margin-block-start (vertical) to create the overlap stack effect."}, {"cls": ".origam-avatar-group__rest", "num": 3, "descriptionKey": "components.avatar_group.anatomy.rest", "descriptionFallback": "Overflow avatar showing the +N count. Visible only when items.length > max. Same overlap margin as __item."}], "classes": [{"cls": "origam-avatar-group", "descriptionKey": "components.avatar_group.anatomy.root", "descriptionFallback": "Root element. inline-flex wrapper with role=\"group\"."}, {"cls": "origam-avatar-group__item", "descriptionKey": "components.avatar_group.anatomy.item", "descriptionFallback": "Each visible avatar with negative overlap margin."}, {"cls": "origam-avatar-group__rest", "descriptionKey": "components.avatar_group.anatomy.rest", "descriptionFallback": "Overflow +N chip avatar shown when items exceed max."}, {"cls": "origam-avatar-group--horizontal", "descriptionKey": "components.avatar_group.anatomy.horizontal", "descriptionFallback": "Stacks avatars left-to-right with negative margin-inline-start."}, {"cls": "origam-avatar-group--vertical", "descriptionKey": "components.avatar_group.anatomy.vertical", "descriptionFallback": "Stacks avatars top-to-bottom with negative margin-block-start."}, {"cls": "origam-avatar-group--expand-on-hover", "descriptionKey": "components.avatar_group.anatomy.expand_on_hover", "descriptionFallback": "Applied when expandOnHover=true. Margins animate to 0 on :hover."}, {"cls": "origam-avatar-group--expand-on-click", "descriptionKey": "components.avatar_group.anatomy.expand_on_click", "descriptionFallback": "Applied when expandOnClick=true. cursor:pointer; toggled by click."}], "svgDesc": "Schematic of the AvatarGroup component with 3 numbered parts.", "svgTitle": "Anatomy of OrigamAvatarGroup", "rootClass": "origam-avatar-group", "figcaption": "Anatomy of <code>&lt;origam-avatar-group&gt;</code> — 3 parts: root wrapper, item avatars and overflow rest chip.", "svgViewBox": "0 0 560 180"}, "cssVars": [{"name": "--origam-avatar-group---position", "defaultValue": "relative", "descriptionKey": "components.avatar_group.css_vars.position", "descriptionFallback": "CSS position of the group root."}, {"name": "--origam-avatar-group---flex-direction", "defaultValue": "row", "descriptionKey": "components.avatar_group.css_vars.flex_direction", "descriptionFallback": "Flex direction. Overridden by direction modifier classes."}, {"name": "--origam-avatar-group---density", "defaultValue": "0px", "descriptionKey": "components.avatar_group.css_vars.density", "descriptionFallback": "Density offset. compact: -6px, comfortable: 10px. Applied to overlap margin calculation."}, {"name": "--origam-avatar-group__item---margin-inline-start", "defaultValue": "calc(-18px + var(--origam-avatar-group---density, 0px))", "descriptionKey": "components.avatar_group.css_vars.item_margin_inline_start", "descriptionFallback": "Horizontal overlap margin for each avatar item (horizontal mode)."}, {"name": "--origam-avatar-group__avatar---transition-duration", "defaultValue": "200ms", "descriptionKey": "components.avatar_group.css_vars.avatar_transition_duration", "descriptionFallback": "Transition duration for the margin animation on expand."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.avatar_group.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.avatar_group.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed group styles."}, {"name": "id", "type": "string", "descriptionKey": "components.avatar_group.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.avatar_group.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.avatar_group.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.avatar_group.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "number", "prop": "max", "labelKey": "components.avatar_group.playground.max", "defaultValue": 4, "labelFallback": "Max visible"}, {"kind": "switch", "prop": "expandOnHover", "labelKey": "components.avatar_group.playground.expand_on_hover", "defaultValue": false, "labelFallback": "Expand on hover"}, {"kind": "switch", "prop": "expandOnClick", "labelKey": "components.avatar_group.playground.expand_on_click", "defaultValue": false, "labelFallback": "Expand on click"}, {"kind": "select", "prop": "direction", "options": [{"label": "horizontal", "value": "horizontal"}, {"label": "vertical", "value": "vertical"}], "labelKey": "components.avatar_group.playground.direction", "defaultValue": "horizontal", "labelFallback": "Direction"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('89037d56-bd65-4a3d-bcd1-da4a19dcc9b5', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'component', 'badge', 'Badge', 'Data Display', NULL, 'mdi-shield-star-outline', 'components.catalog.badge.description', 'Overlay badge for notification counts, status dots and labels, anchored to a wrapped element.', NULL, NULL, 'origam-badge', NULL, 'packages/ds/src/components/Badge/OrigamBadge.vue', 'origam', NULL, NULL, '/stories/?story=components-badge--design', '/docs/components/Badge/OrigamBadge.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.badge.a11y.role_note", "noteFallback": "The badge pill has role=\"status\" with aria-live=\"polite\" and aria-atomic=\"true\". Screen readers announce badge content changes (e.g. new count)."}, {"noteKey": "components.badge.a11y.label_note", "noteFallback": "The label prop (or the translated \"origam.badge\" key) is used as aria-label to describe the badge to screen readers. Pass a meaningful value like \"5 unread notifications\"."}, {"noteKey": "components.badge.a11y.dot_note", "noteFallback": "In dot mode, the content is visually hidden (text-indent: -9999px) but the aria-label still conveys the status to screen readers."}], "roles": ["status"], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-badge__badge---background-color", "descriptionKey": "components.badge.tokens.background_color", "descriptionFallback": "Default badge pill background."}, {"type": "dimension", "value": "var(--origam-radius---full)", "tokenPath": "--origam-badge__badge---border-radius", "descriptionKey": "components.badge.tokens.border_radius", "descriptionFallback": "Full-circle border radius by default."}, {"type": "dimension", "value": "1.25rem", "tokenPath": "--origam-badge__badge---height", "descriptionKey": "components.badge.tokens.height", "descriptionFallback": "Badge pill height (20px)."}, {"type": "dimension", "value": "var(--origam-font__size---sm)", "tokenPath": "--origam-badge__badge---font-size", "descriptionKey": "components.badge.tokens.font_size", "descriptionFallback": "Badge content font size."}, {"type": "color", "value": "var(--origam-color__feedback--danger---bg)", "tokenPath": "--origam-badge--danger---background-color", "descriptionKey": "components.badge.tokens.danger_bg", "descriptionFallback": "Background for error/danger status badges."}, {"type": "duration", "value": "225ms", "tokenPath": "--origam-badge__badge---transition-duration", "descriptionKey": "components.badge.tokens.transition_duration", "descriptionFallback": "Badge position/opacity transition duration."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"220\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"200\" y=\"50\" width=\"300\" height=\"120\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"200\" y=\"50\" width=\"300\" height=\"120\" rx=\"4\" fill=\"none\" stroke=\"var(--origam-color__action--primary---bg, #a855f7)\" stroke-width=\"1\" stroke-dasharray=\"6 3\" opacity=\"0.5\"/>\n  <rect x=\"230\" y=\"80\" width=\"240\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"350\" y=\"115\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#default slot (anchor element)</text>\n  <circle cx=\"475\" cy=\"55\" r=\"20\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"475\" y=\"60\" font-size=\"11\" fill=\"#fff\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" font-weight=\"700\">42</text>\n  <circle cx=\"208\" cy=\"58\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"208\" y=\"62.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"238\" cy=\"88\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"238\" y=\"92\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"463\" cy=\"43\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"463\" y=\"47\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <line x1=\"350\" y1=\"173\" x2=\"350\" y2=\"190\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.5))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"350\" y=\"205\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">Badge pill uses OrigamTransition (fade by default) for show/hide</text>\n", "code": "<div class=\"origam-badge\">\n  <div class=\"origam-badge__wrapper\">\n    <!-- anchor element -->\n    <slot name=\"default\" />\n\n    <!-- badge pill with show/hide transition -->\n    <origam-transition>\n      <span\n        class=\"origam-badge__badge\"\n        role=\"status\"\n        aria-live=\"polite\"\n        aria-atomic=\"true\"\n        :aria-label=\"label\"\n      >\n        <!-- icon or count content -->\n        <span class=\"origam-badge__content\">{{ content }}</span>\n      </span>\n    </origam-transition>\n  </div>\n</div>", "legend": [{"cls": ".origam-badge", "num": 1, "descriptionKey": "components.badge.anatomy.root", "descriptionFallback": "Root element (<code>display: inline-flex</code>). Receives the <code>tag</code> prop (default <code>&lt;div&gt;</code>). Modifiers: <code>--dot</code>, <code>--floating</code>, <code>--inline</code>."}, {"cls": ".origam-badge__wrapper", "num": 2, "descriptionKey": "components.badge.anatomy.wrapper", "descriptionFallback": "Relative-positioned container that anchors the badge pill. Contains the <code>#default</code> slot (the host element)."}, {"cls": ".origam-badge__badge", "num": 3, "descriptionKey": "components.badge.anatomy.badge", "descriptionFallback": "The visible badge pill (<code>position: absolute</code>). Location computed by <code>useLocation</code>. Content capped at <code>max</code>. Wrapped in <code>OrigamTransition</code> for show/hide animation. Has <code>role=\"status\"</code>, <code>aria-live=\"polite\"</code>, <code>aria-atomic=\"true\"</code>."}], "classes": [{"cls": "origam-badge", "descriptionKey": "components.badge.anatomy.root", "descriptionFallback": "Root inline-flex container."}, {"cls": "origam-badge__wrapper", "descriptionKey": "components.badge.anatomy.wrapper", "descriptionFallback": "Relative-positioned wrapper anchoring the badge."}, {"cls": "origam-badge__badge", "descriptionKey": "components.badge.anatomy.badge", "descriptionFallback": "The visible badge pill (absolute positioned, role=\"status\")."}, {"cls": "origam-badge__content", "descriptionKey": "components.badge.anatomy.content", "descriptionFallback": "Text content span inside the badge pill."}, {"cls": "origam-badge__prepend", "descriptionKey": "components.badge.anatomy.prepend", "descriptionFallback": "Leading icon inside the badge pill."}, {"cls": "origam-badge__append", "descriptionKey": "components.badge.anatomy.append", "descriptionFallback": "Trailing icon inside the badge pill."}], "svgDesc": "Schematic of the Badge component with 3 numbered internal parts.", "svgTitle": "Anatomy of OrigamBadge", "rootClass": "origam-badge", "figcaption": "Anatomy of <code>&lt;origam-badge&gt;</code> — 3 parts: root ①, relative wrapper ②, and the absolute-positioned badge pill ③.", "svgViewBox": "0 0 700 220"}, "cssVars": [{"name": "--origam-badge__badge---background-color", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.badge.css_vars.background_color", "descriptionFallback": "Badge pill background. Overridden by color/bgColor prop and status."}, {"name": "--origam-badge__badge---color", "defaultValue": "{color.action.primary.fg}", "descriptionKey": "components.badge.css_vars.color", "descriptionFallback": "Badge pill foreground color."}, {"name": "--origam-badge__badge---border-radius", "defaultValue": "{radius.full}", "descriptionKey": "components.badge.css_vars.border_radius", "descriptionFallback": "Pill border radius. Default is full circle; overridden by rounded prop."}, {"name": "--origam-badge__badge---height", "defaultValue": "1.25rem", "descriptionKey": "components.badge.css_vars.height", "descriptionFallback": "Badge pill height. Fixed at 20px (1.25rem). Shrinks to 9px in dot mode."}, {"name": "--origam-badge__badge---min-width", "defaultValue": "20px", "descriptionKey": "components.badge.css_vars.min_width", "descriptionFallback": "Minimum badge width for circular single-digit display."}, {"name": "--origam-badge__badge---font-size", "defaultValue": "{font.size.sm}", "descriptionKey": "components.badge.css_vars.font_size", "descriptionFallback": "Badge content font size."}, {"name": "--origam-badge__badge---font-weight", "defaultValue": "{font.weight.medium}", "descriptionKey": "components.badge.css_vars.font_weight", "descriptionFallback": "Badge content font weight."}, {"name": "--origam-badge__badge---transition-duration", "defaultValue": "225ms", "descriptionKey": "components.badge.css_vars.transition_duration", "descriptionFallback": "Transition duration for badge position/opacity animations."}], "exposed": [{"n