ayground.show_score", "defaultValue": true, "labelFallback": "Show Score"}, {"kind": "switch", "prop": "showSeed", "labelKey": "components.bracket_competitor.playground.show_seed", "defaultValue": false, "labelFallback": "Show Seed"}, {"kind": "switch", "prop": "interactive", "labelKey": "components.bracket_competitor.playground.interactive", "defaultValue": true, "labelFallback": "Interactive"}]}, "previewVariants": [{"label": "default", "props": {}, "ariaLabel": "Bracket competitor default"}, {"label": "winner", "props": {"isWinner": true}, "ariaLabel": "Bracket competitor winner"}, {"label": "loser", "props": {"isLoser": true}, "ariaLabel": "Bracket competitor loser"}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('2bfbb682-c47f-4ae3-9aea-aba129a97030', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'component', 'bracket-match', 'BracketMatch', 'Data Display', NULL, 'mdi-sword-cross', 'components.catalog.bracket_match.description', 'A single match card inside a tournament bracket, showing two competitor rows with optional meta header (status, schedule, watch link) and score columns.', NULL, NULL, 'origam-bracket-match', NULL, 'packages/ds/src/components/Bracket/OrigamBracketMatch.vue', 'origam', NULL, NULL, '/stories/?story=components-bracket--design', '/docs/components/Bracket/OrigamBracketMatch.html', 'bracket', '{"a11y": {"notes": [{"noteKey": "components.bracket_match.a11y.aria_label_note", "noteFallback": "The root has aria-label=\"Match: A versus B\" computed from competitor names."}, {"noteKey": "components.bracket_match.a11y.live_note", "noteFallback": "The \"Watch live\" link opens in a new tab with rel=\"noopener noreferrer\" for security."}, {"noteKey": "components.bracket_match.a11y.status_note", "noteFallback": "Status badges (LIVE, Completed…) are preceded by a colored dot using ::before — no alt text needed as the text label is present."}, {"noteKey": "components.bracket_match.a11y.reduced_motion_note", "noteFallback": "LIVE badge animation (blink + ping) is disabled under prefers-reduced-motion: reduce."}], "roles": ["group"], "keyboard": [{"key": "Tab", "actionKey": "components.bracket_match.a11y.key_tab", "actionFallback": "Moves focus into the match card and through each competitor row."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"560\" height=\"240\" fill=\"var(--origam-color__surface---sunken, #f9f5ff)\" rx=\"4\"/>\n  <rect x=\"30\" y=\"20\" width=\"500\" height=\"200\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"30\" y=\"20\" width=\"500\" height=\"36\" rx=\"6\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"none\"/>\n  <text x=\"40\" y=\"43\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-family=\"monospace\">LIVE</text>\n  <text x=\"80\" y=\"43\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-family=\"monospace\">14:00 UTC</text>\n  <text x=\"420\" y=\"43\" font-size=\"9\" fill=\"var(--origam-color__feedback--danger---bg, #d32f2f)\" font-family=\"monospace\" font-weight=\"600\">Watch live ↗</text>\n  <line x1=\"30\" y1=\"56\" x2=\"530\" y2=\"56\" stroke=\"var(--origam-color__border---subtle, rgba(0,0,0,0.08))\" stroke-width=\"1\"/>\n  <rect x=\"30\" y=\"56\" width=\"500\" height=\"82\" fill=\"none\"/>\n  <rect x=\"40\" y=\"68\" width=\"480\" height=\"32\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\"/>\n  <text x=\"60\" y=\"88\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" font-family=\"monospace\">Team Alpha</text>\n  <text x=\"490\" y=\"88\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"end\" font-family=\"monospace\" font-weight=\"600\">3</text>\n  <line x1=\"30\" y1=\"138\" x2=\"530\" y2=\"138\" stroke=\"var(--origam-color__border---subtle, rgba(0,0,0,0.08))\" stroke-width=\"1\"/>\n  <rect x=\"40\" y=\"146\" width=\"480\" height=\"32\" rx=\"2\" fill=\"none\"/>\n  <text x=\"60\" y=\"166\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" font-family=\"monospace\" opacity=\"0.7\">Team Beta</text>\n  <text x=\"490\" y=\"166\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"end\" font-family=\"monospace\" font-weight=\"600\">1</text>\n  <circle cx=\"38\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"38\" y=\"32.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"38\" cy=\"60\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"38\" y=\"64.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"280\" cy=\"84\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"280\" y=\"88.5\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"280\" cy=\"162\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"280\" y=\"166.5\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"280\" cy=\"138\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"280\" y=\"142.5\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n", "code": "<div class=\"origam-bracket-match origam-bracket-match--interactive\" role=\"group\">\n  <!-- meta header: visible when status or scheduledAt is set -->\n  <div class=\"origam-bracket-match__meta\">\n    <span class=\"origam-bracket-match__status origam-bracket-match__status--live\">LIVE</span>\n    <a class=\"origam-bracket-match__watch\" href=\"...\" target=\"_blank\" rel=\"noopener noreferrer\">Watch live</a>\n    <span class=\"origam-bracket-match__schedule\">14:00 UTC</span>\n  </div>\n\n  <!-- body: the two competitor rows -->\n  <div class=\"origam-bracket-match__body\">\n    <!-- #competitor slot (side A) -->\n    <origam-bracket-competitor class=\"origam-bracket-match__row\" :is-winner=\"true\" />\n\n    <origam-divider class=\"origam-bracket-match__divider\" />\n\n    <!-- #competitor slot (side B) -->\n    <origam-bracket-competitor class=\"origam-bracket-match__row\" :is-loser=\"true\" />\n  </div>\n</div>", "legend": [{"cls": ".origam-bracket-match", "num": 1, "descriptionKey": "components.bracket_match.anatomy.root", "descriptionFallback": "Root card element. Flex column with border, rounded corners and optional box-shadow. role=\"group\"."}, {"cls": ".origam-bracket-match__meta", "num": 2, "descriptionKey": "components.bracket_match.anatomy.meta", "descriptionFallback": "Meta header bar. Visible only when match.scheduledAt or a resolved status is present. Contains status badge, watch link and schedule time."}, {"cls": ".origam-bracket-match__row (side A)", "num": 3, "descriptionKey": "components.bracket_match.anatomy.row_a", "descriptionFallback": "Competitor A row — an OrigamBracketCompetitor with isWinner/isLoser derived from match.winnerId."}, {"cls": ".origam-bracket-match__row (side B)", "num": 4, "descriptionKey": "components.bracket_match.anatomy.row_b", "descriptionFallback": "Competitor B row — same as A but for the second participant."}, {"cls": ".origam-bracket-match__divider", "num": 5, "descriptionKey": "components.bracket_match.anatomy.divider", "descriptionFallback": "OrigamDivider separator between the two competitor rows."}], "classes": [{"cls": "origam-bracket-match", "descriptionKey": "components.bracket_match.anatomy.root", "descriptionFallback": "Root card element with border and shadow."}, {"cls": "origam-bracket-match__meta", "descriptionKey": "components.bracket_match.anatomy.meta", "descriptionFallback": "Meta header bar with status, watch link and schedule."}, {"cls": "origam-bracket-match__status", "descriptionKey": "components.bracket_match.anatomy.status", "descriptionFallback": "Status badge with colored dot prefix (LIVE / Completed / TBD / Forfeit)."}, {"cls": "origam-bracket-match__body", "descriptionKey": "components.bracket_match.anatomy.body", "descriptionFallback": "Container for the two competitor rows."}, {"cls": "origam-bracket-match__row", "descriptionKey": "components.bracket_match.anatomy.row", "descriptionFallback": "Applied to each OrigamBracketCompetitor inside the body."}, {"cls": "origam-bracket-match__divider", "descriptionKey": "components.bracket_match.anatomy.divider", "descriptionFallback": "Separator between the two competitor rows."}, {"cls": "origam-bracket-match--final", "descriptionKey": "components.bracket_match.anatomy.final", "descriptionFallback": "Final match: elevated shadow, larger card."}, {"cls": "origam-bracket-match--interactive", "descriptionKey": "components.bracket_match.anatomy.interactive", "descriptionFallback": "Hover state: border-color and background-color transition."}], "svgDesc": "Schematic of the BracketMatch card with 5 numbered parts.", "svgTitle": "Anatomy of OrigamBracketMatch", "rootClass": "origam-bracket-match", "figcaption": "Anatomy of <code>&lt;origam-bracket-match&gt;</code> — 5 parts: root card, meta header, body, competitor rows (A / B) and divider.", "svgViewBox": "0 0 560 240"}, "cssVars": [{"name": "--origam-bracket-match---width", "defaultValue": "240px", "descriptionKey": "components.bracket_match.css_vars.width", "descriptionFallback": "Default width of the match card."}, {"name": "--origam-bracket-match---min-height", "defaultValue": "72px", "descriptionKey": "components.bracket_match.css_vars.min_height", "descriptionFallback": "Minimum card height. compact: 56px, comfortable: 88px."}, {"name": "--origam-bracket-match---border-radius", "defaultValue": "6px", "descriptionKey": "components.bracket_match.css_vars.border_radius", "descriptionFallback": "Card border-radius."}, {"name": "--origam-bracket-match---border-color", "defaultValue": "var(--origam-color__border---subtle)", "descriptionKey": "components.bracket_match.css_vars.border_color", "descriptionFallback": "Card border color."}, {"name": "--origam-bracket-match---background-color", "defaultValue": "var(--origam-color__surfac