INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('d80204bf-1777-4a16-bf68-29369cf058f2', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'component', 'breadcrumb', 'Breadcrumb', 'Navigation', NULL, 'mdi-dots-horizontal', 'components.catalog.breadcrumb.description', 'Hierarchical navigation trail rendered as a <nav> landmark with an ordered list of items and configurable dividers.', NULL, NULL, 'origam-breadcrumb', NULL, 'packages/ds/src/components/Breadcrumb/OrigamBreadcrumb.vue', 'origam', NULL, NULL, '/stories/?story=components-breadcrumb--design', '/docs/components/Breadcrumb/OrigamBreadcrumb.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.breadcrumb.a11y.aria_label", "noteFallback": "The root <nav> receives aria-label=\"Breadcrumb\" from the useLocale translation (key: origam.breadcrumb.ariaLabel)."}, {"noteKey": "components.breadcrumb.a11y.aria_current", "noteFallback": "The last item is automatically set to aria-current=\"page\" via the isActive prop on OrigamBreadcrumbItem."}, {"noteKey": "components.breadcrumb.a11y.divider_hidden", "noteFallback": "OrigamBreadcrumbDivider is aria-hidden — the separators are purely presentational and not read by screen readers."}, {"noteKey": "components.breadcrumb.a11y.v_contrast", "noteFallback": "The v-contrast directive is applied to the root for auto contrast when a custom color is set."}, {"noteKey": "components.breadcrumb.a11y.disabled_opacity", "noteFallback": "Disabled items receive opacity-50 and pointer-events: none without the native disabled attribute (which does not apply to anchors)."}], "roles": ["navigation", "list", "listitem"], "keyboard"