#default slot)</text>\n  <rect x=\"20\" y=\"160\" width=\"660\" height=\"20\" rx=\"0\" fill=\"rgba(0,0,0,0.38)\"/>\n  <circle cx=\"320\" cy=\"170\" r=\"5\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\"/>\n  <circle cx=\"340\" cy=\"170\" r=\"5\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <circle cx=\"360\" cy=\"170\" r=\"5\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\"/>\n  <rect x=\"20\" y=\"20\" width=\"32\" height=\"160\" rx=\"4\" fill=\"rgba(0,0,0,0.18)\"/>\n  <text x=\"36\" y=\"105\" font-size=\"18\" fill=\"#fff\" text-anchor=\"middle\">‹</text>\n  <rect x=\"648\" y=\"20\" width=\"32\" height=\"160\" rx=\"4\" fill=\"rgba(0,0,0,0.18)\"/>\n  <text x=\"664\" y=\"105\" font-size=\"18\" fill=\"#fff\" text-anchor=\"middle\">›</text>\n  <rect x=\"20\" y=\"20\" width=\"660\" height=\"4\" rx=\"0\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" opacity=\"0.7\"/>\n  <circle cx=\"28\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"28\" cy=\"164\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"28\" y=\"168\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"340\" cy=\"164\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"340\" y=\"168\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"36\" cy=\"32\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"36\" y=\"36\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"350\" cy=\"24\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"350\" y=\"28\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <text x=\"350\" y=\"220\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">⑤ progress bar is absolutely positioned at top; ② controls strip sits at bottom</text>\n", "code": "<!-- root wraps OrigamWindow -->\n<origam-window class=\"origam-carousel\">\n  <!-- slide items projected here -->\n  <slot name=\"default\" />\n\n  <!-- additional content: dots + progress -->\n  <template #additional>\n    <!-- pagination dots (hidden when hideDelimiters) -->\n    <div class=\"origam-carousel__controls\">\n      <origam-btn\n        v-for=\"(item, index) in items\"\n        :key=\"index\"\n        class=\"origam-carousel__controls-item\"\n      />\n    </div>\n\n    <!-- progress bar (visible when progress=true) -->\n    <div class=\"origam-carousel__progress\">\n      <origam-progress-linear :model-value=\"progressPercent\" />\n    </div>\n  </template>\n</origam-window>", "legend": [{"cls": ".origam-carousel", "num": 1, "descriptionKey": "components.carousel.anatomy.root", "descriptionFallback": "Root element. Delegates slide rendering to an inner OrigamWindow."}, {"cls": ".origam-carousel__controls", "num": 2, "descriptionKey": "components.carousel.anatomy.controls", "descriptionFallback": "Absolute strip at the bottom. Contains the delimiter (dot) buttons. Hidden when hideDelimiters=true."}, {"cls": ".origam-carousel__controls-item", "num": 3, "descriptionKey": "components.carousel.anatomy.controls_item", "descriptionFallback": "One pagination dot — an OrigamBtn rendered per slide. Gets --active modifier when its slide is selected."}, {"cls": ".origam-carousel__controls-item--active", "num": 4, "descriptionKey": "components.carousel.anatomy.controls_item_active", "descriptionFallback": "BEM modifier applied to the active dot. Icon opacity rises from 0.5 to 1."}, {"cls": ".origam-carousel__progress", "num": 5, "descriptionKey": "components.carousel.anatomy.progress", "descriptionFallback": "Absolute strip at the top. Wraps OrigamProgressLinear. Visible only when progress=true."}], "classes": [{"cls": "origam-carousel", "descriptionKey": "components.carousel.anatomy.root", "descriptionFallback": "Root carousel element."}, {"cls": "origam-carousel__controls", "descriptionKey": "components.carousel.anatomy.controls", "descriptionFallback": "Pagination dots strip, absolutely positioned at the bottom."}, {"cls": "origam-carousel__controls-item", "descriptionKey": "components.carousel.anatomy.controls_item", "descriptionFallback": "Single pagination dot button."}, {"cls": "origam-carousel__controls-item--active", "descriptionKey": "components.carousel.anatomy.controls_item_active", "descriptionFallback": "Active state on the current slide dot."}, {"cls": "origam-carousel__progress", "descriptionKey": "components.carousel.anatomy.progress", "descriptionFallback": "Progress bar container, absolutely positioned at the top."}], "svgDesc": "Schematic of the Carousel component with 5 numbered internal parts.", "svgTitle": "Anatomy of OrigamCarousel", "rootClass": "origam-carousel", "figcaption": "Anatomy of <code>&lt;origam-carousel&gt;</code> — 5 internal parts.", "svgViewBox": "0 0 700 240"}, "cssVars": [{"name": "--origam-carousel---overflow", "defaultValue": "hidden", "descriptionKey": "components.carousel.css_vars.overflow", "descriptionFallback": "Overflow mode of the carousel root."}, {"name": "--origam-carousel---position", "defaultValue": "relative", "descriptionKey": "components.carousel.css_vars.position", "descriptionFallback": "CSS position of the root element."}, {"name": "--origam-carousel---width", "defaultValue": "100%", "descriptionKey": "components.carousel.css_vars.width", "descriptionFallback": "Root width."}, {"name": "--origam-carousel__controls---background-color", "defaultValue": "rgba(0, 0, 0, 0.4)", "descriptionKey": "components.carousel.css_vars.controls_bg", "descriptionFallback": "Background of the pagination dots strip."}, {"name": "--origam-carousel__controls---height", "defaultValue": "50px", "descriptionKey": "components.carousel.css_vars.controls_height", "descriptionFallback": "Height of the controls strip."}, {"name": "--origam-carousel__controls---z-index", "defaultValue": "{zIndex.raised}", "descriptionKey": "components.carousel.css_vars.controls_z_index", "descriptionFallback": "Z-index of the controls strip, ensuring it renders above slide content."}, {"name": "--origam-carousel__controls-item---opacity", "defaultValue": "0.5", "descriptionKey": "components.carousel.css_vars.controls_item_opacity", "descriptionFallback": "Default icon opacity inside a pagination dot."}, {"name": "--origam-carousel__controls-item---opacity-active", "defaultValue": "1", "descriptionKey": "components.carousel.css_vars.controls_item_opacity_active", "descriptionFallback": "Icon opacity inside the active pagination dot."}, {"name": "--origam-carousel__progress---position-top", "defaultValue": "0", "descriptionKey": "components.carousel.css_vars.progress_position_top", "descriptionFallback": "Top offset of the progress bar. Set to auto and provide bottom to move it."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.carousel.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.carousel.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed carousel styles."}, {"name": "id", "type": "string", "descriptionKey": "components.carousel.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.carousel.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.carousel.exposed.un