<circle class=\"origam-chart-box-plot__outlier\" />\n  </g>\n</g>", "legend": [{"cls": ".origam-chart-box-plot", "num": 1, "descriptionKey": "components.chart_box_plot.anatomy.root", "descriptionFallback": "Root SVG element containing all box plots."}, {"cls": ".origam-chart-box-plot__box", "num": 2, "descriptionKey": "components.chart_box_plot.anatomy.box", "descriptionFallback": "IQR rectangle from Q1 to Q3."}, {"cls": ".origam-chart-box-plot__median", "num": 3, "descriptionKey": "components.chart_box_plot.anatomy.median", "descriptionFallback": "Horizontal line at the median (Q2)."}, {"cls": ".origam-chart-box-plot__whisker", "num": 4, "descriptionKey": "components.chart_box_plot.anatomy.whisker", "descriptionFallback": "Vertical whisker lines extending from Q1/Q3 to min/max fences, plus cap segments."}, {"cls": ".origam-chart-box-plot__outlier", "num": 5, "descriptionKey": "components.chart_box_plot.anatomy.outlier", "descriptionFallback": "Outlier dot circles rendered when showOutliers=true."}], "classes": [{"cls": "origam-chart-box-plot", "descriptionKey": "components.chart_box_plot.anatomy.root", "descriptionFallback": "Root SVG group."}, {"cls": "origam-chart-box-plot__slot", "descriptionKey": "components.chart_box_plot.anatomy.slot", "descriptionFallback": "Per-category slot group."}, {"cls": "origam-chart-box-plot__box", "descriptionKey": "components.chart_box_plot.anatomy.box", "descriptionFallback": "IQR box rectangle."}, {"cls": "origam-chart-box-plot__median", "descriptionKey": "components.chart_box_plot.anatomy.median", "descriptionFallback": "Median line."}, {"cls": "origam-chart-box-plot__whisker", "descriptionKey": "components.chart_box_plot.anatomy.whisker", "descriptionFallback": "Whisker lines and caps."}, {"cls": "origam-chart-box-plot__outlier", "descriptionKey": "components.chart_box_plot.anatomy.outlier", "descriptionFallback": "Outlier dot circles."}], "svgDesc": "Schematic showing a box, whiskers and outlier dot.", "svgTitle": "Anatomy of 