var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"44\" y=\"64.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <text x=\"62\" y=\"64\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #666)\" font-family=\"system-ui\">Header — prepend / title / append</text>\n  <rect x=\"28\" y=\"92\" width=\"644\" height=\"58\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---subtle, rgba(124,58,237,0.2))\" stroke-width=\"1\"/>\n  <circle cx=\"44\" cy=\"121\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"44\" y=\"125.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <text x=\"62\" y=\"125\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #666)\" font-family=\"system-ui\">#default — Primary input field</text>\n  <rect x=\"28\" y=\"158\" width=\"644\" height=\"58\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---subtle, rgba(124,58,237,0.2))\" stroke-width=\"1\"/>\n  <circle cx=\"44\" cy=\"187\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"44\" y=\"191.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <text x=\"62\" y=\"191\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #666)\" font-family=\"system-ui\">#confirm — Confirmation input field</text>\n  <rect x=\"28\" y=\"224\" width=\"644\" height=\"28\" rx=\"4\" fill=\"none\"/>\n  <circle cx=\"44\" cy=\"238\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"44\" y=\"242.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <text x=\"62\" y=\"242\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #666)\" font-family=\"system-ui\">Details — messages / hint / counter</text>\n", "code": "<div class=\"origam-confirm-wrapper\">\n\n  <!-- header (conditional: prepend / title / append) -->\n  <div class=\"origam-confirm-wrapper__header\">\n    <div class=\"origam-confirm-wrapper__prepend\"><slot name=\"prepend\"/></div>\n    <div class=\"origam-confirm-wrapper__label\"><slot name=\"title\"/></div>\n    <div class=\"origam-confirm-wrapper__append\"><slot name=\"append\"/></div>\n  </div>\n\n  <!-- field row -->\n  <div class=\"origam-confirm-wrapper__content\">\n    <div class=\"origam-confirm-wrapper__field\">\n      <slot name=\"default\" />  <!-- primary input -->\n    </div>\n    <div class=\"origam-confirm-wrapper__confirm\">\n      <slot name=\"confirm\" />  <!-- confirmation input -->\n    </div>\n  </div>\n\n  <!-- details / messages -->\n  <div class=\"origam-confirm-wrapper__details\">\n    <slot name=\"messages\" />\n  </div>\n</div>", "legend": [{"cls": ".origam-confirm-wrapper", "num": 1, "descriptionKey": "components.confirm_wrapper.anatomy.root", "descriptionFallback": "Root element. Manages shared validation state between the two inner inputs."}, {"cls": ".origam-confirm-wrapper__header", "num": 2, "descriptionKey": "components.confirm_wrapper.anatomy.header", "descriptionFallback": "Optional header row. Contains prepend, title and append sub-elements. Hidden when no header content is provided."}, {"cls": ".origam-confirm-wrapper__field", "num": 3, "descriptionKey": "components.confirm_wrapper.anatomy.field", "descriptionFallback": "Primary input container. The <code>#default</code> slot renders here."}, {"cls": ".origam-confirm-wrapper__confirm", "num": 4, "descriptionKey": "components.confirm_wrapper.anatomy.confirm", "descriptionFallback": "Confirmation input container. The <code>#confirm</code> slot renders here."}, {"cls": ".origam-confirm-wrapper__details", "num": 5, "descriptionKey": "components.confirm_wrapper.anatomy.details", "descriptionFallback": "Details row. Shows hint, messages and match-error text. Height governed by <code>--origam-confirm-wrapper---details-min-height</code>."}], "classes": [{"cls": "origam-confirm-wrapper", "descriptionKey": "components.confirm_wrapper.anatomy.root", "descriptionFallback": "Root container. Manages shared form validation."}, {"cls": "origam-confirm-wrapper__header", "descriptionKey": "components.confirm_wrapper.anatomy.header", "descriptionFallback": "Header row with prepend / label / append regions."}, {"cls": "origam-confirm-wrapper__prepend", "descriptionKey": "components.confirm_wrapper.anatomy.prepend", "descriptionFallback": "Leading icon/avatar area in the header."}, {"cls": "origam-confirm-wrapper__label", "descriptionKey": "components.confirm_wrapper.anatomy.label", "descriptionFallback": "Title area in the header."}, {"cls": "origam-confirm-wrapper__append", "descriptionKey": "components.confirm_wrapper.anatomy.append", "descriptionFallback": "Trailing icon/avatar area in the header."}, {"cls": "origam-confirm-wrapper__content", "descriptionKey": "components.confirm_wrapper.anatomy.content", "descriptionFallback": "Flex container holding both input slots (direction-aware: vertical / horizontal)."}, {"cls": "origam-confirm-wrapper__field", "descriptionKey": "components.confirm_wrapper.anatomy.field", "descriptionFallback": "Primary input slot wrapper."}, {"cls": "origam-confirm-wrapper__confirm", "descriptionKey": "components.confirm_wrapper.anatomy.confirm", "descriptionFallback": "Confirmation input slot wrapper."}, {"cls": "origam-confirm-wrapper__details", "descriptionKey": "components.confirm_wrapper.anatomy.details", "descriptionFallback": "Messages and hint area below the inputs."}], "svgDesc": "Schematic of the ConfirmWrapper component with numbered internal parts.", "svgTitle": "Anatomy of OrigamConfirmWrapper", "rootClass": "origam-confirm-wrapper", "figcaption": "Anatomy of <code>&lt;origam-confirm-wrapper&gt;</code> — 5 regions. The wrapper coordinates validation between the #default and #confirm slots, surfacing match errors in the details zone.", "svgViewBox": "0 0 700 280"}, "cssVars": [{"name": "--origam-confirm-wrapper---padding-start", "defaultValue": "{space.2}", "descriptionKey": "components.confirm_wrapper.css_vars.padding_start", "descriptionFallback": "Inline-start (left in LTR) padding of the wrapper."}, {"name": "--origam-confirm-wrapper---padding-end", "defaultValue": "{space.2}", "descriptionKey": "components.confirm_wrapper.css_vars.padding_end", "descriptionFallback": "Inline-end (right in LTR) padding of the wrapper."}, {"name": "--origam-confirm-wrapper---padding-top", "defaultValue": "{space.2}", "descriptionKey": "components.confirm_wrapper.css_vars.padding_top", "descriptionFallback": "Block-start padding of the wrapper."}, {"name": "--origam-confirm-wrapper---padding-bottom", "defaultValue": "{space.4}", "descriptionKey": "components.confirm_wrapper.css_vars.padding_bottom", "descriptionFallback": "Block-end padding of the wrapper."}, {"name": "--origam-confirm-wrapper---details-min-height", "defaultValue": "22px", "descriptionKey": "components.confirm_wrapper.css_vars.details_min_height", "descriptionFallback": "Minimum height of the details row to prevent layout shift when messages appear."}, {"name": "--origam-confirm-wrapper---horizontal-gap", "defaultValue": "1em", "descriptionKey": "components.confirm_wrapper.css_vars.horizontal_gap", "descriptionFallback": "Gap between primary and confirmation fields in horizontal direction mode."}, {"name": "--origam-confirm-wrapper--error---color", "defaultValue": "{color.feedback.danger.fgSubtle}", "descriptionKey": "components.confirm_wrapper.css_vars.error_color", "descriptionFallback": "Error text color rendered in the details row when values do not match."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.confirm_wrapper.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": "validate", "type": "() => Promise<boolean>", "descriptionKey": "components.confirm_wrapper.exposed.validate", "descriptionFallback": "Triggers validation of both fields. Resolves to true when values match and all rules pass."}, {"name": "reset", "type": "() => void", "descriptionKey": "components.confirm_wrapper.exposed.reset", "descriptionFallback": "Resets both input values and clears validation state."}, {"name": "resetValidation", "type": "() => void", "descriptionKey": "components.confirm_wrapper.exposed.reset_validation", "descriptionFallback": "Clears validation messages without resetting values."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.confirm_wrapper.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle for the injected style sheet."}, {"name": "id", "type": "string", "descriptionKey": "components.confirm_wrapper.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.confirm_wrapper.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.confirm_wrapper.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.confirm_wrapper.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "variant", "options": [{"label": "outlined", "value": "outlined"}, {"label": "filled", "value": "filled"}, {"label": "plain", "value": "plain"}, {"label": "underlined", "value": "underlined"}, {"label": "solo", "value": "solo"}], "labelKey": "components.confirm_wrapper.playground.variant", "defaultValue": "outlined", "labelFallback": "Variant"}, {"kind": "select", 