origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"78\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">grid-column / grid-row / grid-area</text>\n  <rect x=\"60\" y=\"90\" width=\"580\" height=\"48\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"119\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#default slot</text>\n  <circle cx=\"36\" cy=\"48\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"52.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"68\" cy=\"98\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"68\" y=\"102.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <line x1=\"46\" y1=\"44\" x2=\"88\" y2=\"28\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"92\" y=\"28\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-grid-item</text>\n", "legend": [{"cls": ".origam-grid-item", "num": 1, "descriptionKey": "components.grid_item.anatomy.root", "descriptionFallback": "Root element. Sets <code>grid-column</code>, <code>grid-row</code> or <code>grid-area</code> via inline styles. Also applies <code>min-width: 0; min-height: 0</code> to prevent overflow."}, {"cls": ".origam-grid-item #default", "num": 2, "descriptionKey": "components.grid_item.anatomy.slot", "descriptionFallback": "Default slot hosting the cell content. No constraints imposed — content defines its own sizing."}], "svgDesc": "Schematic of the GridItem component with 2 numbered internal parts.", "svgTitle": "Anatomy of OrigamGridItem", "rootClass": "origam-grid-item", "figcaption": "Anatomy of <code>&lt;origam-grid-item&gt;</code> — 2 parts: the root element carrying grid placement styles, and the default slot hosting the cell content.", "svgViewBox": "0 0 700 200"}, "cssVars": [], "exposed": [{"name": "columnCss", "type": "ComputedRef<string | undefined>", "descriptionKey": "components.grid_item.exposed.column_css", "descriptionFallback": "Serialised grid-column value derived from the column prop. Readable by parent tooling."}, {"name": "rowCss", "type": "ComputedRef<string | undefined>", "descriptionKey": "components.grid_item.exposed.row_css", "descriptionFallback": "Serialised grid-row value derived from the row prop."}], "playground": {"controls": [{"kind": "select", "prop": "alignSelf", "options": [{"label": "(default)", "value": ""}, {"label": "start", "value": "start"}, {"label": "center", "value": "center"}, {"label": "end", "value": "end"}, {"label": "stretch", "value": "stretch"}], "labelKey": "components.grid_item.playground.align_self", "defaultValue": "", "labelFallback": "Align Self"}, {"kind": "select", "prop": "justifySelf", "options": [{"label": "(default)", "value": ""}, {"label": "start", "value": "start"}, {"label": "center", "value": "center"}, {"label": "end", "value": "end"}, {"label": "stretch", "value": "stretch"}], "labelKey": "components.grid_item.playground.justify_self", "defaultValue": "", "labelFallback": "Justify Self"}], "defaultSlotContent": "Content"}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('5c4c0b8c-a254-412d-b7d1-024dc070c729', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'component', 'icon', 'Icon', 'Media', NULL, 'mdi-star-four-points', 'components.catalog.icon.description', 'Universal icon renderer that adapts to MDI class icons, SVG paths, component-based icons and Unicode ligatures.', NULL, NULL, 'origam-icon', NULL, 'packages/ds/src/components/Icon/OrigamIcon.vue', 'origam', NULL, NULL, '/stories/?story=components-icon--design', '/docs/components/Icon/OrigamIcon.html', NULL, '{"playground": {"controls": [{"kind": "switch", "prop": "disabled", "labelKey": "components.icon.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}], "defaultSlotContent": "Content"}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('98dcd724-d566-4133-bfb4-e4df92dd263b', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'component', 'img', 'Img', 'Data Display', NULL, 'mdi-image-outline', 'components.catalog.img.description', 'Responsive image component with lazy loading, aspect-ratio enforcement, placeholder and error slot, optional gradient overlay, srcset / sizes support, and a smooth fade-in transition on load.', NULL, NULL, 'origam-img', NULL, 'packages/ds/src/components/Img/OrigamImg.vue', 'origam', NULL, NULL, '/stories/?story=components-img--design', '/docs/components/Img/OrigamImg.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.img.a11y.alt", "noteFallback": "Always provide a meaningful alt text. When alt is present, role=\"img\" and aria-label={alt} are set on the root. For decorative images, omit alt and set aria-hidden=\"true\" on the parent."}, {"noteKey": "components.img.a11y.lazy_loading", "noteFallback": "Lazy loading is handled via IntersectionObserver (not the native loading=\"lazy\" attribute) so the component loads the image only when it enters the viewport. The placeholder slot is announced by the browser as the alt text is still present on the root."}, {"noteKey": "components.img.a11y.error_slot", "noteFallback": "When the image fails to load, the #error slot is shown. The slot content should include meaningful text or an icon-with-label so users know the image did not load."}, {"noteKey": "components.img.a11y.reduced_motion", "noteFallback": "The fade-in transition respects prefers-reduced-motion. When the user prefers reduced motion, set transition=\"false\" or use --origam-img---transition-duration: 0ms."}], "roles": ["img"], "keyboard": []}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"16\" width=\"644\" height=\"168\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"48\" y=\"36\" width=\"604\" height=\"108\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"350\" y=\"80\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__picture (absolute, object-fit: contain/cover)</text>\n  <rect x=\"200\" y=\"52\" width=\"300\" height=\"40\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"350\" y=\"76\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">__placeholder (lazy load blur)</text>\n  <rect x=\"48\" y=\"156\" width=\"604\" height=\"20\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.15))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"350\" y=\"170\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">#default slot (overlay content)</text>\n  <circle cx=\"36\" cy=\"24\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"28.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"56\" cy=\"44\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"56\" y=\"48\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"200\" cy=\"56\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"200\" y=\"60\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n", "code": "<!-- OrigamImg — wraps OrigamResponsive for aspect ratio -->\n<origam-responsive\n  v-intersect=\"intersect\"\n  :aria-label=\"alt\"\n  :aspect-ratio=\"aspectRatio\"\n  :role=\"alt ? ''img'' : undefined\"\n  class=\"origam-img\"\n>\n  <template #additional>\n    <!-- main image (fade-in on load) -->\n    <origam-transition :transition=\"transition\">\n      <img v-show=\"isLoaded\" class=\"origam-img__picture origam-img__picture--cover\" />\n    </origam-transition>\n\n    <!-- lazySrc placeholder (blur filter) -->\n    <origam-transition :transition=\"transition\">\n      <img v-if=\"lazySrc && !isLoaded\" class=\"origam-img__picture origam-img__picture--preload\" />\n    </origam-transition>\n\n    <!-- #placeholder slot — v-if isLoading && slots.placeholder -->\n    <div v-if=\"(isLoading || isError) && slots.placeholder\" class=\"origam-img__placeholder\">\n      <slot name=\"placeholder\" />\n    </div>\n\n    <!-- #error slot — v-if isError && slots.error -->\n    <div v-if=\"isError && slots.error\" class=\"origam-img__error\">\n      <slot name=\"error\" />\n    </div>\n\n    <!-- gradient overlay — v-if gradient -->\n    <div v-if=\"gradient\" class=\"origam-img__gradient\" />\n  </template>\n\n  <!-- #default slot — overlay content -->\n  <template #default v-if=\"hasContent\">\n    <slot name=\"default\" />\n  </template>\n</origam-responsive>", "legend": [{"cls": ".origam-img", "num": 1, "descriptionKey": "components.img.anatomy.root", "descriptionFallback": "Root element wrapping OrigamResponsive. Carries role=\"img\" when alt is present. Has --booting modifier until aspectRatio resolves."}, {"cls": ".origam-img__picture", "num": 2, "descriptionKey": "components.img.anatomy.picture", "descriptionFallback": "Native <img> element. Absolutely positioned, 100% width/height. Has --cover (object-fit: cover) or --contain (object-fit: contain) modifier. Has --preload modifier with blur filter when showing lazySrc."}, {"cls": ".origam-img__placeholder", "num": 3, "descriptionKey": "components.img.anatomy.placeholder", "descriptionFallback": "Shown during loading (or lazySrc phase) when the #placeholder slot is provided. Absolutely positioned layer behind the main image."}, {"cls": ".origam-img__error", "num": 4, "descriptionKey": "components.img.anatomy.error", "descriptionFallback": "Shown when the image fails to load and the #error slot is provided."}, {"cls": ".origam-img__gradient", "num": 5, "descriptionKey": "components.img.anatomy.gradient", "descriptionFallback": "Absolutely positioned <div> rendered when gradient prop is set. Applies background-image: linear-gradient(...)."}], "classes": [{"cls": "origam-img", "descriptionKey": "components.img.anatomy.root", "descriptionFallback": "Root element. Has --booting class until aspectRatio resolves (prevents premature paint)."}, {"cls": "origam-img--booting", "descriptionKey": "components.img.anatomy.booting", "descriptionFallback": "Disables the sizer transition during initial mount. Removed after first rAF."}, {"cls": "origam-img__picture", "descriptionKey": "components.img.anatomy.picture", "descriptionFallback": "Native <img>. Always absolutely positioned inside the responsive sizer."}, {"cls": "origam-img__picture--cover", "descriptionKey": "components.img.anatomy.picture_cover", "descriptionFallback": "object-fit: cover — image fills the container, cropped."}, {"cls": "origam-img__picture--contain", "descriptionKey": "components.img.anatomy.picture_contain", "descriptionFallback": "object-fit: contain — image fits inside the container without cropping."}, {"cls": "origam-img__picture--preload", "descriptionKey": "components.img.anatomy.picture_preload", "descriptionFallback": "Applied to the lazySrc image. Has blur filter while the full-res image loads."}, {"cls": "origam-img__placeholder", "descriptionKey": "components.img.anatomy.placeholder", "descriptionFallback": "#placeholder slot wrapper. Shown during loading."}, {"cls": "origam-img__error", "descriptionKey": "components.img.anatomy.error", "descriptionFallback": "#error slot wrapper. Shown on load failure."}, {"cls": "origam-img__gradient", "descriptionKey": "components.img.anatomy.gradient", "descriptionFallback": "Gradient overlay div. background-image set from the gradient prop."}], "svgDesc": "Schematic of the Img component with 5 numbered internal parts.", "svgTitle": "Anatomy of OrigamImg", "rootClass": "origam-img", "figcaption": "Anatomy of <code>&lt;origam-img&gt;</code> — 5 internal parts. The root ① wraps OrigamResponsive for aspect-ratio enforcement. The picture ② is absolutely positioned. Placeholder ③ and error ④ layers are conditional. The gradient ⑤ is an absolute div when the gradient prop is set.", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-img---background-color", "defaultValue": "{color.surface.overlay}", "descriptionKey": "components.img.css_vars.background_color", "descriptionFallback": "Background colour of the image container while the image loads."}, {"name": "--origam-img---border-radius", "defaultValue": "{radius.none} (0px)", "descriptionKey": "components.img.css_vars.border_radius", "descriptionFallback": "Corner radius of the image root. Overridden by the rounded prop."}, {"name": "--origam-img---transition-duration", "defaultValue": "{motion.duration.medium}", "descriptionKey": "components.img.css_vars.transition_duration", "descriptionFallback": "Fade-in transition duration when the image loads."}, {"name": "--origam-img__picture--preload---filter", "defaultValue": "blur(4px)", "descriptionKey": "components.img.css_vars.picture_preload_filter", "descriptionFallback": "CSS filter applied to the lazySrc placeholder image."}, {"name": "--origam-img__picture--contain---object-fit", "defaultValue": "contain", "descriptionKey": "components.img.css_vars.picture_contain_object_fit", "descriptionFallback": "object-fit value for the --contain modifier."}, {"name": "--origam-img__picture--cover---object-fit", "defaultValue": "cover", "descriptionKey": "components.img.css_vars.picture_cover_object_fit", "descriptionFallback": "object-fit value for the --cover modifier."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.img.exposed.filter_props", "descriptionFallback": "Filters and forwards a subset of props."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.img.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.img.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.img.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.img.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "ComputedRef<boolean>", "descriptionKey": "components.img.exposed.is_loaded", "descriptionFallback": "True when the image has successfully loaded (state === LOADED)."}, {"name": "styleIsLoaded", "type": "Ref<boolean>", "descriptionKey": "components.img.exposed.style_is_loaded", "descriptionFallback": "True once the component style sheet has been injected. Note: distinct from isLoaded (image load state)."}], "playground": {"controls": [{"kind": "text", "prop": "src", "labelKey": "components.img.playground.src", "defaultValue": "https://picsum.photos/600/400", "labelFallback": "Source URL"}, {"kind": "text", "prop": "alt", "labelKey": "components.img.playground.alt", "defaultValue": "Landscape photo", "labelFallback": "Alt text"}, {"kind": "switch", "prop": "cover", "labelKey": "components.img.playground.cover", "defaultValue": false, "labelFallback": "Cover (vs contain)"}, {"kind": "select", "prop": "aspectRatio", "options": [{"label": "(auto)", "value": ""}, {"label": "16/9", "value": "1.7778"}, {"label": "4/3", "value": "1.3333"}, {"label": "1/1 (square)", "value": "1"}, {"label": "3/4 (portrait)", "value": "0.75"}], "labelKey": "components.img.playground.aspect_ratio", "defaultValue": "", "labelFallback": "Aspect ratio"}, {"kind": "select", "prop": "rounded", "options": [{"label": "(none)", "value": ""}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "lg", "value": "lg"}, {"label": "xl", "value": "xl"}, {"label": "pill", "value": "pill"}], "labelKey": "components.img.playground.rounded", "defaultValue": "", "labelFallback": "Rounded"}, {"kind": "select", "prop": "gradient", "options": [{"label": "(none)", "value": ""}, {"label": "to bottom (dark)", "value": "to bottom, transparent, rgba(0,0,0,0.6)"}, {"label": "to top (dark)", "value": "to top, transparent, rgba(0,0,0,0.6)"}], "labelKey": "components.img.playground.gradient", "defaultValue": "", "labelFallback": "Gradient"}]}, "previewVariants": [{"label": "contain", "props": {"alt": "Photo (contain)", "src": "https://picsum.photos/400/300", "width": 200, "aspectRatio": "4/3"}}, {"label": "cover", "props": {"alt": "Photo (cover)", "src": "https://picsum.photos/400/300", "cover": true, "width": 200, "aspectRatio": "4/3"}}, {"label": "rounded", "props": {"alt": "Rounded photo", "src": "https://picsum.photos/300/300", "cover": true, "width": 120, "rounded": "xl", "aspectRatio": 1}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('ea1d7418-1505-4be8-bbc3-4def897ff44e', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'component', 'infinite-scroll', 'InfiniteScroll', 'Data Display', NULL, 'mdi-infinity', 'components.catalog.infinite_scroll.description', 'Sentinel-based infinite scroll that fires a load event when the user reaches the start or end of a scrollable area.', NULL, NULL, 'origam-infinite-scroll', NULL, 'packages/ds/src/components/InfiniteScroll/OrigamInfiniteScroll.vue', 'origam', NULL, NULL, '/stories/?story=components-infinite-scroll--design', '/docs/components/InfiniteScroll/OrigamInfiniteScroll.html', NULL, '{"playground": {"controls": [{"kind": "select", "prop": "side", "options": [{"label": "(default)", "value": ""}, {"label": "start", "value": "start"}, {"label": "end", "value": "end"}, {"label": "both", "value": "both"}], "labelKey": "components.infinite_scroll.playground.side", "defaultValue": "", "labelFallback": "Side"}, {"kind": "select", "prop": "mode", "options": [{"label": "(default)", "value": ""}, {"label": "intersect", "value": "intersect"}, {"label": "manual", "value": "manual"}], "labelKey": "components.infinite_scroll.playground.mode", "defaultValue": "", "labelFallback": "Mode"}, {"kind": "select", "prop": "direction", "options": [{"label": "(default)", "value": ""}, {"label": "horizontal", "value": "horizontal"}, {"label": "vertical", "value": "vertical"}], "labelKey": "components.infinite_scroll.playground.direction", "defaultValue": "", "labelFallback": "Direction"}], "defaultSlotContent": "Content"}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('21027965-cab3-44c3-9833-8186ebef7927', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'component', 'infinite-scroll-intersect', 'InfiniteScrollIntersect', 'Data Display', NULL, 'mdi-arrow-collapse-down', 'components.catalog.infinite_scroll_intersect.description', 'Low-level sentinel element used by InfiniteScroll to detect when the scroll boundary enters the viewport via IntersectionObserver.', NULL, NULL, 'origam-infinite-scroll-intersect', NULL, 'packages/ds/src/components/InfiniteScroll/OrigamInfiniteScrollIntersect.vue', 'origam', NULL, NULL, '/stories/?story=components-infinite-scroll--design', '/docs/components/InfiniteScroll/OrigamInfiniteScroll.html', 'infinite-scroll', '{"a11y": {"notes": [{"noteKey": "components.infinite_scroll_intersect.a11y.invisible_note", "noteFallback": "The sentinel is a non-interactive, invisible element with no ARIA role. Screen readers ignore it. Announce newly loaded content via a live region on the parent component."}], "roles": [], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-infinite-scroll__loader---color", "descriptionKey": "components.infinite_scroll_intersect.tokens.loader_color", "descriptionFallback": "Color passed to the OrigamProgress spinner in the loading slot."}, {"type": "dimension", "value": "var(--origam-space---3)", "tokenPath": "--origam-infinite-scroll__loader---gap", "descriptionKey": "components.infinite_scroll_intersect.tokens.loader_gap", "descriptionFallback": "Gap between loader and adjacent elements within the side zone."}, {"type": "color", "value": "var(--origam-color__text---secondary)", "tokenPath": "--origam-infinite-scroll__empty---color", "descriptionKey": "components.infinite_scroll_intersect.tokens.empty_color", "descriptionFallback": "Text color for the empty-state message shown when no more items are available."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"160\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"40\" width=\"644\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" stroke-dasharray=\"6 3\"/>\n  <text x=\"350\" y=\"84\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">height: 1px (invisible sentinel)</text>\n  <circle cx=\"36\" cy=\"48\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"52.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <line x1=\"46\" y1=\"44\" x2=\"88\" y2=\"28\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"92\" y=\"28\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-infinite-scroll-intersect</text>\n", "legend": [{"cls": ".origam-infinite-scroll-intersect", "num": 1, "descriptionKey": "components.infinite_scroll_intersect.anatomy.root", "descriptionFallback": "Root element. A minimal <code>&lt;div&gt;</code> containing a non-breaking space (<code>&amp;nbsp;</code>) to ensure the browser paints it. Observed by <code>useIntersectionObserver</code> and fires the <code>intersect</code> emit on visibility change."}], "svgDesc": "Schematic of the InfiniteScrollIntersect sentinel element with 1 numbered part.", "svgTitle": "Anatomy of OrigamInfiniteScrollIntersect", "rootClass": "origam-infinite-scroll-intersect", "figcaption": "Anatomy of <code>&lt;origam-infinite-scroll-intersect&gt;</code> — a single invisible sentinel <code>&lt;div&gt;</code> observed by an IntersectionObserver.", "svgViewBox": "0 0 700 160"}, "cssVars": [{"name": "--origam-infinite-scroll---loader-color", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.infinite_scroll_intersect.css_vars.loader_color", "descriptionFallback": "Color of the loading spinner in the parent InfiniteScroll loader slot."}, {"name": "--origam-infinite-scroll---loader-gap", "defaultValue": "{space.3}", "descriptionKey": "components.infinite_scroll_intersect.css_vars.loader_gap", "descriptionFallback": "Gap between the loader and adjacent elements in the side zone."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.infinite_scroll_intersect.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}], "playground": {"controls": [{"kind": "select", "prop": "side", "options": [{"label": "(default)", "value": ""}, {"label": "start", "value": "start"}, {"label": "INFINITE_SCROLL_SIDE.START", "value": "INFINITE_SCROLL_SIDE.START"}, {"label": "INFINITE_SCROLL_SIDE.END", "value": "INFINITE_SCROLL_SIDE.END"}, {"label": "end", "value": "end"}, {"label": "INFINITE_SCROLL_SIDE.BOTH", "value": "INFINITE_SCROLL_SIDE.BOTH"}, {"label": "both", "value": "both"}], "labelKey": "components.infinite_scroll_intersect.playground.side", "defaultValue": "", "labelFallback": "Side"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('962390a2-3204-4e2a-b42b-368dc93df0ab', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'component', 'list-item', 'ListItem', 'Data Display', NULL, 'mdi-format-list-bulleted', 'components.catalog.list_item.description', 'Single row inside a List. Supports prepend/append icons or avatars, title, subtitle, active state, and polymorphic link rendering.', NULL, NULL, 'origam-list-item', NULL, 'packages/ds/src/components/List/OrigamListItem.vue', 'origam', NULL, NULL, '/stories/?story=components-list-item--design', '/docs/components/List/OrigamListItem.html', 'list', '{"a11y": {"notes": [{"noteKey": "components.list_item.a11y.disabled_note", "noteFallback": "When disabled=true and rendered as an anchor, aria-disabled=\"true\" is set instead of the disabled attribute. Pointer events are removed via CSS."}, {"noteKey": "components.list_item.a11y.link_note", "noteFallback": "When href or to is set, the item renders as a native <a> element — full keyboard navigation and focus management are inherited from the browser."}, {"noteKey": "components.list_item.a11y.selection_note", "noteFallback": "When inside a selectable list (value prop set), selection state is driven by useNestedItem. The active CSS class provides a visual selected indicator."}], "roles": [], "keyboard": [{"key": "Enter / Space", "actionKey": "components.list_item.a11y.key_activate", "actionFallback": "Activates a clickable item (fires click event, navigates, or toggles selection)."}, {"key": "Tab", "actionKey": "components.list_item.a11y.key_tab", "actionFallback": "Moves focus. tabindex=0 for standalone clickable items; tabindex=-2 inside a list group."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "56px", "tokenPath": "--origam-list__item---min-height", "descriptionKey": "components.list_item.tokens.min_height", "descriptionFallback": "Default minimum row height."}, {"type": "dimension", "value": "var(--origam-space---4)", "tokenPath": "--origam-list-item---padding-inline-start", "descriptionKey": "components.list_item.tokens.padding_inline_start", "descriptionFallback": "Default inline-start padding (16px). Added to list indent-padding and density."}, {"type": "color", "value": "currentColor", "tokenPath": "--origam-list__item---overlay-background-color", "descriptionKey": "components.list_item.tokens.overlay_background_color", "descriptionFallback": "Overlay tint color for hover/active states."}, {"type": "dimension", "value": "var(--origam-font__size---lg)", "tokenPath": "--origam-list__item---title-font-size", "descriptionKey": "components.list_item.tokens.title_font_size", "descriptionFallback": "Title font size (1rem)."}, {"type": "dimension", "value": "var(--origam-font__size---md)", "tokenPath": "--origam-list__item---subtitle-font-size", "descriptionKey": "components.list_item.tokens.subtitle_font_size", "descriptionFallback": "Subtitle font size (0.875rem)."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"220\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"30\" width=\"660\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"20\" y=\"30\" width=\"660\" height=\"80\" rx=\"4\" fill=\"none\" stroke=\"var(--origam-color__action--primary---bg, #a855f7)\" stroke-width=\"1\" stroke-dasharray=\"6 3\" opacity=\"0.6\"/>\n  <rect x=\"32\" y=\"42\" width=\"56\" height=\"56\" rx=\"3\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.4))\" stroke-width=\"1.5\"/>\n  <text x=\"60\" y=\"74\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">prepend</text>\n  <rect x=\"100\" y=\"42\" width=\"416\" height=\"56\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <rect x=\"108\" y=\"50\" width=\"248\" height=\"16\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.10))\"/>\n  <text x=\"232\" y=\"62\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">title</text>\n  <rect x=\"108\" y=\"74\" width=\"180\" height=\"12\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\"/>\n  <text x=\"198\" y=\"84\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">subtitle</text>\n  <rect x=\"528\" y=\"42\" width=\"140\" height=\"56\" rx=\"3\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.4))\" stroke-width=\"1.5\"/>\n  <text x=\"598\" y=\"74\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">append</text>\n  <rect x=\"20\" y=\"30\" width=\"660\" height=\"80\" rx=\"4\" fill=\"none\"/>\n  <rect x=\"20\" y=\"110\" width=\"660\" height=\"4\" rx=\"0\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.12))\"/>\n  <circle cx=\"28\" cy=\"38\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"42\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"60\" cy=\"38\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"60\" y=\"42\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"308\" cy=\"38\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"308\" y=\"42\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"232\" cy=\"46\" r=\"8\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"232\" y=\"50\" font-size=\"8\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"198\" cy=\"70\" r=\"8\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"198\" y=\"74\" font-size=\"8\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <circle cx=\"598\" cy=\"38\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"598\" y=\"42\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n  <circle cx=\"28\" cy=\"108\" r=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"28\" y=\"112\" font-size=\"8\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">7</text>\n  <line x1=\"38\" y1=\"36\" x2=\"90\" y2=\"18\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"94\" y=\"20\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-list-item</text>\n  <text x=\"350\" y=\"200\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">⑦ = overlay — absolute, opacity: 0 at rest, visible on hover/active</text>\n", "legend": [{"cls": ".origam-list-item", "num": 1, "descriptionKey": "components.list_item.anatomy.root", "descriptionFallback": "Root element. Renders as <code>&lt;div&gt;</code> by default, <code>&lt;a&gt;</code> when href/to is set. Grid container: 3 columns (prepend / content / append)."}, {"cls": ".origam-list-item__prepend", "num": 2, "descriptionKey": "components.list_item.anatomy.prepend", "descriptionFallback": "Leading icon/avatar zone. <code>grid-area: prepend</code>. Renders <code>prependIcon</code>, <code>prependAvatar</code>, or the <code>#prepend</code> slot. <code>v-if=\"hasPrepend\"</code>."}, {"cls": ".origam-list-item__content", "num": 3, "descriptionKey": "components.list_item.anatomy.content", "descriptionFallback": "<code>grid-area: content</code>. Contains title, subtitle and the <code>#default</code> slot."}, {"cls": ".origam-list-item__title", "num": 4, "descriptionKey": "components.list_item.anatomy.title", "descriptionFallback": "Primary text. Truncates with ellipsis (white-space: nowrap). <code>v-if=\"hasTitle\"</code>."}, {"cls": ".origam-list-item__subtitle", "num": 5, "descriptionKey": "components.list_item.anatomy.subtitle", "descriptionFallback": "Secondary text. Uses <code>-webkit-box</code> clamp via the <code>lines</code> prop. <code>v-if=\"hasSubtitle\"</code>."}, {"cls": ".origam-list-item__append", "num": 6, "descriptionKey": "components.list_item.anatomy.append", "descriptionFallback": "Trailing icon/avatar zone. <code>grid-area: append</code>. Renders <code>appendIcon</code>, <code>appendAvatar</code>, or the <code>#append</code> slot. <code>v-if=\"hasAppend\"</code>."}, {"cls": ".origam-list-item__overlay", "num": 7, "descriptionKey": "components.list_item.anatomy.overlay", "descriptionFallback": "Absolute interaction scrim. <code>opacity: 0</code> at rest → 0.08 on hover/focus → 0.12 when active. Only rendered when the item is clickable or active."}], "svgDesc": "Schematic of the ListItem component with 7 numbered internal parts.", "svgTitle": "Anatomy of OrigamListItem", "rootClass": "origam-list-item", "figcaption": "Anatomy of <code>&lt;origam-list-item&gt;</code> — 7 internal parts. The grid layout places prepend ② / content ③ / append ⑥ in a 3-column grid. Title ④ and subtitle ⑤ live inside content. The overlay ⑦ is an absolute layer that paints hover/active tints.", "svgViewBox": "0 0 700 220"}, "cssVars": [{"name": "--origam-list-item---min-height", "defaultValue": "40px", "descriptionKey": "components.list_item.css_vars.min_height", "descriptionFallback": "Minimum row height. Adjusted by the density modifier."}, {"name": "--origam-list-item---padding-block-start", "defaultValue": "8px", "descriptionKey": "components.list_item.css_vars.padding_block_start", "descriptionFallback": "Block-start padding. Added to the density offset."}, {"name": "--origam-list-item---padding-inline-start", "defaultValue": "16px", "descriptionKey": "components.list_item.css_vars.padding_inline_start", "descriptionFallback": "Inline-start padding. Added to the indent-padding and density offsets."}, {"name": "--origam-list-item---border-radius", "defaultValue": "0px", "descriptionKey": "components.list_item.css_vars.border_radius", "descriptionFallback": "Item border radius. Overridden by the rounded prop."}, {"name": "--origam-list-item---cursor", "defaultValue": "pointer", "descriptionKey": "components.list_item.css_vars.cursor", "descriptionFallback": "Cursor style when the item is in link/clickable mode."}, {"name": "--origam-list-item---opacity", "defaultValue": "0.6", "descriptionKey": "components.list_item.css_vars.opacity", "descriptionFallback": "Opacity applied when the item is disabled."}, {"name": "--origam-list-item__overlay---opacity", "defaultValue": "0", "descriptionKey": "components.list_item.css_vars.overlay_opacity", "descriptionFallback": "Overlay opacity. Animates to 0.08 on hover/focus and 0.12 when active."}, {"name": "--origam-list-item__title---font-size", "defaultValue": "1rem", "descriptionKey": "components.list_item.css_vars.title_font_size", "descriptionFallback": "Title font size. Overridden to 0.8125rem in nav mode."}, {"name": "--origam-list-item__subtitle---font-size", "defaultValue": "0.875rem", "descriptionKey": "components.list_item.css_vars.subtitle_font_size", "descriptionFallback": "Subtitle font size."}], "exposed": [{"name": "isGroupActivator", "type": "boolean", "descriptionKey": "components.list_item.exposed.is_group_activator", "descriptionFallback": "True when this item acts as the activator of a ListGroup. Prevents selection toggling on click."}, {"name": "isSelected", "type": "Ref<boolean>", "descriptionKey": "components.list_item.exposed.is_selected", "descriptionFallback": "Reactive selection state from useNestedItem. True when the item value is selected in the parent list."}, {"name": "list", "type": "ListProvide | null", "descriptionKey": "components.list_item.exposed.list", "descriptionFallback": "Parent list context injected by OrigamList. Null when the item is used standalone."}, {"name": "select", "type": "(value: boolean, event?: Event) => void", "descriptionKey": "components.list_item.exposed.select", "descriptionFallback": "Programmatically select or deselect this item within the parent list."}, {"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.list_item.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.list_item.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed listItemStyles."}, {"name": "load", "type": "() => void", "descriptionKey": "components.list_item.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.list_item.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.list_item.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "text", "prop": "title", "labelKey": "components.list_item.playground.title", "defaultValue": "List item", "labelFallback": "Title"}, {"kind": "text", "prop": "subtitle", "labelKey": "components.list_item.playground.subtitle", "defaultValue": "", "labelFallback": "Subtitle"}, {"kind": "select", "prop": "prependIcon", "options": [{"label": "(none)", "value": ""}, {"label": "mdi-inbox", "value": "mdi-inbox"}, {"label": "mdi-account", "value": "mdi-account"}, {"label": "mdi-star", "value": "mdi-star"}, {"label": "mdi-home", "value": "mdi-home"}], "labelKey": "components.list_item.playground.prepend_icon", "defaultValue": "mdi-inbox", "labelFallback": "Prepend icon"}, {"kind": "select", "prop": "lines", "options": [{"label": "(default)", "value": ""}, {"label": "one-line", "value": "one-line"}, {"label": "two-line", "value": "two-line"}, {"label": "three-line", "value": "three-line"}], "labelKey": "components.list_item.playground.lines", "defaultValue": "", "labelFallback": "Lines"}, {"kind": "switch", "prop": "active", "labelKey": "components.list_item.playground.active", "defaultValue": false, "labelFallback": "Active"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.list_item.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}]}, "previewVariants": [{"label": "simple", "props": {"title": "Inbox", "prependIcon": "mdi-inbox"}}, {"label": "subtitle", "props": {"title": "John Doe", "subtitle": "john.doe@example.com", "prependIcon": "mdi-account"}}, {"label": "active", "props": {"title": "Active", "active": true, "prependIcon": "mdi-star"}}, {"label": "disabled", "props": {"title": "Disabled", "disabled": true, "prependIcon": "mdi-lock"}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
