Absolute"}], "defaultSlotContent": "Content"}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('446134c3-9ebc-483c-ae7f-800ec14c0188', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'component', 'row', 'Row', 'Layout & Structure', NULL, 'mdi-table-row', 'components.catalog.row.description', 'Horizontal flex row that wraps Col children with configurable gutters, alignment, justify and direction. Sub-component of the Grids family.', NULL, NULL, 'origam-row', NULL, 'packages/ds/src/components/Grids/OrigamRow.vue', 'origam', NULL, NULL, '/stories/?story=components-grids--design', '/docs/components/Grids/OrigamGrids.html', 'grids', '{"a11y": {"notes": [{"noteKey": "components.row.a11y.semantic_note", "noteFallback": "Row renders a plain div by default. For sectioning content, override the tag prop with a semantic element such as section or main."}], "roles": [], "keyboard": []}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"30\" width=\"660\" height=\"120\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" stroke-dasharray=\"6 3\"/>\n  <rect x=\"40\" y=\"55\" width=\"190\" height=\"70\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1.5\"/>\n  <text x=\"135\" y=\"94\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Col slot</text>\n  <rect x=\"255\" y=\"55\" width=\"190\" height=\"70\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"94\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Col slot</text>\n  <rect x=\"470\" y=\"55\" width=\"190\" height=\"70\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1.5\"/>\n  <text x=\"565\" y=\"94\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Col slot</text>\n  <circle cx=\"28\" cy=\"38\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"42\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"50\" cy=\"63\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"50\" y=\"67\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"350\" cy=\"40\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"350\" y=\"44\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n", "code": "<!-- root: flex container, tag configurable -->\n<div class=\"origam-row origam-row--density-default origam-row--align-stretch origam-row--justify-start\">\n  <!-- default slot: Col children -->\n  <slot name=\"default\" />\n</div>", "legend": [{"cls": ".origam-row", "num": 1, "descriptionKey": "components.row.anatomy.root", "descriptionFallback": "Root element. Renders as a flex container (display: flex, flex-wrap: wrap). Tag is configurable via the tag prop."}, {"cls": ".origam-row (Col children)", "num": 2, "descriptionKey": "components.row.anatomy.cols", "descriptionFallback": "Direct Col children receive gutter via negative margin on the row and padding on each Col."}, {"cls": ".origam-row--density-{compact|default|comfortable}", "num": 3, "descriptionKey": "components.row.anatomy.density", "descriptionFallback": "Density modifier class. Adjusts --origam-row---density offset on block and inline margins."}], "classes": [{"cls": "origam-row", "descriptionKey": "components.row.anatomy.root", "descriptionFallback": "Root flex container."}, {"cls": "origam-row--density-default", "descriptionKey": "components.row.anatomy.density_default", "descriptionFallback": "Default density (0 offset)."}, {"cls": "origam-row--density-compact", "descriptionKey": "components.row.anatomy.density_compact", "descriptionFallback": "Compact density (−8px margin offset)."}, {"cls": "origam-row--density-comfortable", "descriptionKey": "components.row.anatomy.density_comfortable", "descriptionFallback": "Comfortable density (+8px margin offset)."}, {"cls": "origam-row--align-{value}", "descriptionKey": "components.row.anatomy.align", "descriptionFallback": "Sets --origam-row---align-items. Values: start, end, center, baseline, stretch."}, {"cls": "origam-row--justify-{value}", "descriptionKey": "components.row.anatomy.justify", "descriptionFallback": "Sets --origam-row---justify-content. Values: start, end, center, space-between, space-around, space-evenly."}, {"cls": "origam-row--direction-{value}", "descriptionKey": "components.row.anatomy.direction", "descriptionFallback": "Sets --origam-row---flex-direction. Values: row, row-reverse, column, column-reverse."}, {"cls": "origam-row--border", "descriptionKey": "components.row.anatomy.border", "descriptionFallback": "Applied when border prop is set. Activates border-width and box-shadow tokens."}], "svgDesc": "Schematic of the Row component with 3 numbered parts.", "svgTitle": "Anatomy of OrigamRow", "rootClass": "origam-row", "figcaption": "Anatomy of <code>&lt;origam-row&gt;</code> — 3 parts: root flex container ①, Col children ②, density-driven margin adjustment ③.", "svgViewBox": "0 0 700 180"}, "cssVars": [{"name": "--origam-row---display", "defaultValue": "flex", "descriptionKey": "components.row.css_vars.display", "descriptionFallback": "Display value for the row (always flex)."}, {"name": "--origam-row---flex-direction", "defaultValue": "row", "descriptionKey": "components.row.css_vars.flex_direction", "descriptionFallback": "Flex direction. Overridden by direction prop class."}, {"name": "--origam-row---flex-wrap", "defaultValue": "wrap", "descriptionKey": "components.row.css_vars.flex_wrap", "descriptionFallback": "Wrap mode. Default: wrap (columns stack on overflow)."}, {"name": "--origam-row---flex", "defaultValue": "1 1 auto", "descriptionKey": "components.row.css_vars.flex", "descriptionFallback": "Flex shorthand applied to the row itself."}, {"name": "--origam-row---align-items", "defaultValue": "stretch", "descriptionKey": "components.row.css_vars.align_items", "descriptionFallback": "Cross-axis alignment. Overridden by align / alignSm … alignXxl classes."}, {"name": "--origam-row---justify-content", "defaultValue": "flex-start", "descriptionKey": "components.row.css_vars.justify_content", "descriptionFallback": "Main-axis distribution. Overridden by justify / justifySm … justifyXxl classes."}, {"name": "--origam-row---margin-block-start", "defaultValue": "-4px", "descriptionKey": "components.row.css_vars.margin_block_start", "descriptionFallback": "Default negative block-start margin that creates gutters with Col padding."}, {"name": "--origam-row---margin-inline-start", "defaultValue": "-4px", "descriptionKey": "components.row.css_vars.margin_inline_start", "descriptionFallback": "Default negative inline-start margin."}, {"name": "--origam-row---density", "defaultValue": "0px", "descriptionKey": "components.row.css_vars.density", "descriptionFallback": "Density offset added to block and inline margins. compact: −8px, comfortable: +8px."}, {"name": "--origam-row--border---border-width", "defaultValue": "{border.width.1}", "descriptionKey": "components.row.css_vars.border_width", "descriptionFallback": "Border width when the border modifier class is active."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.row.exposed.filter_props", "descriptionFallback": "Forwards a filtered subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.row.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from computed row styles."}, {"name": "id", "type": "string", "descriptionKey": "components.row.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.row.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.row.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.row.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.row.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}, {"kind": "select", "prop": "bgColor", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.row.playground.bg_color", "defaultValue": "", "labelFallback": "Background color"}, {"kind": "select", "prop": "density", "options": [{"label": "(default)", "value": ""}, {"label": "default", "value": "default"}, {"label": "DENSITY.DEFAULT", "value": "DENSITY.DEFAULT"}, {"label": "compact", "value": "compact"}, {"label": "DENSITY.COMPACT", "value": "DENSITY.COMPACT"}, {"label": "DENSITY.COMFORTABLE", "value": "DENSITY.COMFORTABLE"}, {"label": "comfortable", "value": "comfortable"}], "labelKey": "components.row.playground.density", "defaultValue": "", "labelFallback": "Density"}, {"kind": "select", "prop": "align", "options": [{"label": "(default)", "value": ""}, {"label": "start", "value": "start"}, {"label": "center", "value": "center"}, {"label": "end", "value": "end"}, {"label": "stretch", "value": "stretch"}, {"label": "baseline", "value": "baseline"}], "labelKey": "components.row.playground.align", "defaultValue": "", "labelFallback": "Align"}, {"kind": "select", "prop": "justify", "options": [{"label": "(default)", "value": ""}, {"label": "start", "value": "start"}, {"label": "center", "value": "center"}, {"label": "end", "value": "end"}, {"label": "space-between", "value": "space-between"}, {"label": "space-around", "value": "space-around"}, {"label": "space-evenly", "value": "space-evenly"}], "labelKey": "components.row.playground.justify", "defaultValue": "", "labelFallback": "Justify"}, {"kind": "select", "prop": "direction", "options": [{"label": "(default)", "value": ""}, {"label": "FLEX_DIRECTION.ROW", "value": "FLEX_DIRECTION.ROW"}, {"label": "row", "value": "row"}, {"label": "column", "value": "column"}, {"label": "FLEX_DIRECTION.COLUMN", "value": "FLEX_DIRECTION.COLUMN"}, {"label": "FLEX_DIRECTION.COLUMN_RE