inline=true. Switches flex-direction from column to row."}, {"cls": "[slot: item / item.{index}]", "num": 3, "descriptionKey": "components.selection_control_group.anatomy.slot_item", "descriptionFallback": "Items slot rendered per entry in the items array. Wrapped in OrigamDefaultsProvider so group-level props (color, type, density, disabled…) are inherited by children."}], "classes": [{"cls": "origam-selection-control-group", "descriptionKey": "components.selection_control_group.anatomy.root", "descriptionFallback": "Root block. Display: flex, flex-direction: column by default."}, {"cls": "origam-selection-control-group--inline", "descriptionKey": "components.selection_control_group.anatomy.inline", "descriptionFallback": "Applied when inline=true. Changes flex-direction to row."}], "svgDesc": "Schematic of SelectionControlGroup with 3 numbered parts.", "svgTitle": "Anatomy of OrigamSelectionControlGroup", "rootClass": "origam-selection-control-group", "figcaption": "Anatomy of <code>&lt;origam-selection-control-group&gt;</code> — root group ① wraps SelectionControl children ② via OrigamDefaultsProvider. The item slot ③ controls how each item is rendered.", "svgViewBox": "0 0 560 200"}, "cssVars": [{"name": "--origam-selection-control-group---display", "defaultValue": "flex", "descriptionKey": "components.selection_control_group.css_vars.display", "descriptionFallback": "Display mode for the group container (always flex)."}, {"name": "--origam-selection-control-group---flex-direction", "defaultValue": "column", "descriptionKey": "components.selection_control_group.css_vars.flex_direction", "descriptionFallback": "Stack direction. Switches to row when --inline modifier is applied."}, {"name": "--origam-selection-control-group---flex-direction-inline", "defaultValue": "row", "descriptionKey": "components.selection_control_group.css_vars.flex_direction_inline", "descriptionFallback": "Flex direction when inline=true."}, {"name": "--origam-selection-control-group---flex-wrap", "defaultValue": "wrap", "descriptionKey": "components.selection_control_group.css_vars.flex_wrap", "descriptionFallback": "Wrap mode for inline groups."}, {"name": "--origam-selection-control-group---gap", "defaultValue": "{space.2}", "descriptionKey": "components.selection_control_group.css_vars.gap", "descriptionFallback": "Gap between child SelectionControl items."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.selection_control_group.exposed.filter_props", "descriptionFallback": "Forwards a filtered subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.selection_control_group.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "ComputedRef<string>", "descriptionKey": "components.selection_control_group.exposed.id", "descriptionFallback": "Computed group id (props.id or auto-generated origam-selection-control-group-{uid})."}, {"name": "styleId", "type": "string", "descriptionKey": "components.selection_control_group.exposed.style_id", "descriptionFallback": "Unique style-sheet ID for this instance (distinct from the logical group id)."}, {"name": "load", "type": "() => void", "descriptionKey": "components.selection_control_group.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.selection_control_group.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.selection_control_group.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "select", "prop": "type", "options": [{"label": "checkbox", "value": "checkbox"}, {"label": "radio", "value": "radio"}], "labelKey": "components.selection_control_group.playground.type", "defaultValue": "checkbox", "labelFallback": "Type"}, {"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}], "labelKey": "components.selection_control_group.playground.color", "defaultValue": "primary", "labelFallback": "Color"}, {"kind": "switch", "prop": "inline", "labelKey": "components.selection_control_group.playground.inline", "defaultValue": false, "labelFallback": "Inline"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.selection_control_group.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "error", "labelKey": "components.selection_control_group.playground.error", "defaultValue": false, "labelFallback": "Error"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('7c831de0-33db-4deb-881d-404a184a7a38', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'component', 'sheet', 'Sheet', 'Overlay & Surface', NULL, 'mdi-card-outline', 'components.catalog.sheet.description', 'General-purpose surface container with optional swipe-to-expand bottom-sheet gesture. Used as the base layer for Dialog, Picker, ColorPickerField and other overlay components.', NULL, NULL, 'origam-sheet', NULL, 'packages/ds/src/components/Sheet/OrigamSheet.vue', 'origam', NULL, NULL, '/stories/?story=components-sheet--design', '/docs/components/Sheet/OrigamSheet.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.sheet.a11y.handle_note", "noteFallback": "The drag handle has role=\"button\", tabindex=\"0\" and aria-label=\"Drag handle\" so keyboard users can navigate snap points without touch."}, {"noteKey": "components.sheet.a11y.reduced_motion_note", "noteFallback": "Under prefers-reduced-motion, the height transition is disabled. Height still changes imperatively but without animation."}, {"noteKey": "components.sheet.a11y.overlay_note", "noteFallback": "OrigamSheet is a surface-only primitive. Overlay focus-trap and aria-modal semantics are managed by the Dialog or Drawer wrapper using this component."}], "roles": [], "keyboard": [{"key": "Tab (handle)", "actionKey": "components.sheet.a11y.key_tab", "actionFallback": "Focuses the drag handle button when swipeable=true."}, {"key": "Enter / Space (handle)", "actionKey": "components.sheet.a11y.key_enter", "actionFallback": "Cycles through snap points when the handle is focused."}]}, "tokens": {"exce