INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('373b44f8-e931-4825-aba9-e9ac8a92dd8f', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'component', 'skeleton', 'Skeleton', 'Feedback & Status', NULL, 'mdi-shimmer', 'components.catalog.skeleton.description', 'Loading placeholder with an opacity pulse. Supports text, rectangular, circular and pill variants — primitives to compose inside an OrigamSkeletonGroup. Renders real content via the default slot when loading=false.', NULL, NULL, 'origam-skeleton', NULL, 'packages/ds/src/components/Skeleton/OrigamSkeleton.vue', 'origam', NULL, NULL, '/stories/?story=components-skeleton--design', '/docs/components/Skeleton/OrigamSkeleton.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.skeleton.a11y.role_note", "noteFallback": "Each skeleton block has role=\"status\", aria-busy=\"true\" and aria-label=\"Loading\". This ensures screen readers announce the loading state without repeating a full description."}, {"noteKey": "components.skeleton.a11y.reduced_motion_note", "noteFallback": "The pulse animation is disabled under prefers-reduced-motion: reduce. The skeleton remains visible as a static placeholder."}, {"noteKey": "components.skeleton.a11y.content_note", "noteFallback": "When loading=false, the skeleton is replaced by real content via the default slot. Ensure the revealed content is semantically correct (headings, alt text, etc.)."}], "roles": ["status"], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "color-mix(in srgb, currentColor 10%, transparent)", "tokenPath": "--origam-skeleton---background-color", "descriptionKey": "components.skeleton.tokens.background_color", "descriptionFallback": "Base placeholder background color."}, {"type": "dimension", "value": "var(--origam-radius---sm)", "tokenPath": "--origam-skeleton---border-radius", "descriptionKey": "components.skeleton.tokens.border_radius", "descriptionFallback": "Border-radius for text and rectangular variants."}, {"type": "dimension", "value": "var(--origam-radius---full)", "tokenPath": "--origam-skeleton---border-radius-circular", "descriptionKey": "components.skeleton.tokens.border_radius_circular", "descriptionFallback": "Border-radius for circular variant."}, {"type": "duration", "value": "var(--origam-motion__duration---loop)", "tokenPath": "--origam-skeleton---animation-duration", "descriptionKey": "components.skeleton.tokens.animation_duration", "descriptionFallback": "Pulse animation duration."}, {"type": "dimension", "value": "0.7em", "tokenPath": "--origam-skeleton---text-height", "descriptionKey": "components.skeleton.tokens.text_height", "descriptionFallback": "Text variant line height."}, {"type": "dimension", "value": "var(--origam-space---3)", "tokenPath": "--origam-skeleton---gap", "descriptionKey": "components.skeleton.tokens.gap", "descriptionFallback": "Gap of an OrigamSkeletonGroup."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"560\" height=\"100\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <text x=\"30\" y=\"30\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-family=\"''JetBrains Mono'',monospace\" font-style=\"italic\">rectangular variant (standalone)</text>\n  <rect x=\"20\" y=\"44\" width=\"520\" height=\"40\" rx=\"2\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.18))\"/>\n  <circle cx=\"28\" cy=\"52\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"56\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n", "code": "<!-- loading=false → render real content -->\n<template v-if=\"!loading\">\n  <slot />\n</template>\n\n<!-- placeholder block (text / rectangular / circular / pill) -->\n<div\n  v-else\n  class=\"origam-skeleton origam-skeleton--rectangular origam--skeleton\"\n  role=\"status\"\n  aria-busy=\"true\"\n  aria-label=\"Loading\"\n/>", "legend": [{"cls": ".origam-skeleton", "num": 1, "descriptionKey": "components.skeleton.anatomy.standalone", "descriptionFallback": "The single-block element rendered for every variant (text, rectangular, circular, pill). Inside an OrigamSkeletonGroup it is aria-hidden and the group makes the one announcement."}], "classes": [{"cls": "origam-skeleton", "descriptionKey": "components.skeleton.anatomy.block", "descriptionFallback": "Core skeleton block. Carries the shimmer background and animation."}, {"cls": "origam-skeleton--text", "descriptionKey": "components.skeleton.anatomy.modifier_text", "descriptionFallback": "Text-height variant (1.2em tall, 100% wide by default)."}, {"cls": "origam-skeleton--rectangular", "descriptionKey": "components.skeleton.anatomy.modifier_rectangular", "descriptionFallback": "Full-height rectangular block."}, {"cls": "origam-skeleton--circular", "descriptionKey": "components.skeleton.anatomy.modifier_circular", "descriptionFallback": "Circular block. Height mirrors width."}], "svgDesc": "Schematic of the Skeleton component with 1 numbered part: the placeholder block.", "svgTitle": "Anatomy of OrigamSkeleton", "rootClass": "origam-skeleton", "figcaption": "Anatomy of <code>&lt;origam-skeleton&gt;</code> — 1 part: the placeholder block ①.", "svgViewBox": "0 0 560 100"}, "cssVars": [{"name": "--origam-skeleton---background-color", "defaultValue": "{color.surface.overlay}", "descriptionKey": "components.skeleton.css_vars.background_color", "descriptionFallback": "Base background color of the skeleton block."}, {"name": "--origam-skeleton---border-radius", "defaultValue": "{radius.sm}", "descriptionKey": "components.skeleton.css_vars.border_radius", "descriptionFallback": "Border-radius for text and rectangular variants."}, {"name": "--origam-skeleton---border-radius-circular", "defaultValue": "{radius.full}", "descriptionKey": "components.skeleton.css_vars.border_radius_circular", "descriptionFallback": "Border-radius for circular variant (50% = full circle)."}, {"name": "--origam-skeleton---animation-duration", "defaultValue": "{motion.duration.xslow}", "descriptionKey": "components.skeleton.css_vars.animation_duration", "descriptionFallback": "Duration of the shimmer / spin animation."}, {"name": "--origam-skeleton---text-height", "defaultValue": "1.2em", "descriptionKey": "components.skeleton.css_vars.text_height", "descriptionFallback": "Height of the text variant block."}, {"name": "--origam-skeleton---gap", "defaultValue": "{space.3}", "descriptionKey": "components.skeleton.css_vars.gap", "descriptionFallback": "Gap of an OrigamSkeletonGroup."}, {"name": "--origam-skeleton---wave-color", "defaultValue": "color-mix(in srgb, {skeleton.background-color} 50%, white)", "descriptionKey": "components.skeleton.css_vars.wave_color", "descriptionFallback": "Highlight color of the shimmer wave. Derived from background-color by default."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.skeleton.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.skeleton.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.skeleton.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.skeleton.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.skeleton.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.skeleton.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "select", "prop": "variant", "options": [{"label": "text", "value": "text"}, {"label": "rectangular", "value": "rectangular"}, {"label": "circular", "value": "circular"}], "labelKey": "components.skeleton.playground.variant", "defaultValue": "rectangular", "labelFallback": "Variant"}, {"kind": "switch", "prop": "pulse", "labelKey": "components.skeleton.playground.pulse", "defaultValue": true, "labelFallback": "Pulse animation"}, {"kind": "switch", "prop": "loading", "labelKey": "components.skeleton.playground.loading", "defaultValue": true, "labelFallback": "Loading"}, {"kind": "select", "prop": "rounded", "options": [{"label": "(default)", "value": ""}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "lg", "value": "lg"}, {"label": "pill", "value": "pill"}], "labelKey": "components.skeleton.playground.rounded", "defaultValue": "", "labelFallback": "Rounded"}]}, "previewVariants": [{"label": "text", "props": {"width": 200, "variant": "text"}}, {"label": "rectangular", "props": {"width": 200, "height": 80, "variant": "rectangular"}}, {"label": "circular", "props": {"width": 48, "variant": "circular"}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
