INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('6526e3b9-5ec4-4d12-a7c1-ba8a3c148c9a', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'composable', 'use-locale', 'useLocale', NULL, 'Commons', 'mdi-translate', '', 'Injects the Origam locale instance created by createLocale() (or the vue-i18n adapter wired in createOrigam()). Provides the current locale ref, the RTL flag, and the translation function used by all internal DS components. Throws if called outside a createOrigam context.', NULL, 'function useLocale(): ILocaleInstance & IRtlInstance', NULL, NULL, 'packages/ds/src/composables/Commons/locale.composable.ts', NULL, NULL, 'useLocale exposes the DS-internal translation keys only. For application-level i18n (your own strings), keep using @nuxtjs/i18n or vue-i18n directly. The DS adapter wires into your existing i18n instance when configured via createOrigam({ locale: { adapter } }).', NULL, NULL, NULL, '{"consumedInterfaces": ["ILocaleInstance", "ILocaleOptions", "IRtlInstance"]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
