INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('4c55bf61-01c7-4154-8435-08f959a76cbe', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'composable', 'use-scroll-strategies', 'useScrollStrategies', 'Commons', 'Commons', NULL, NULL, NULL, NULL, 'function useScrollStrategies(props: IScrollStrategyProps, data: IScrollStrategyData): void', NULL, NULL, 'packages/ds/src/composables/Commons/scrollStrategies.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('34735d03-4f8f-49cc-912f-58cc5703411f', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'composable', 'use-select', 'useSelection', NULL, 'DataTable', 'mdi-checkbox-multiple-marked-outline', '', 'Inject accessor for the row-selection context provided by provideSelection inside OrigamDataTable. Returns the reactive selected Set and the select / toggleSelect / selectAll helpers plus status flags (someSelected, allSelected, showSelectAll). Used by checkbox columns and the header select-all control.', NULL, 'function useSelection(): IDataTableProvideSelection', NULL, NULL, 'packages/ds/src/composables/DataTable/select.composable.ts', NULL, NULL, 'useSelection throws when called outside a DataTable context (no inject match for ORIGAM_DATA_TABLE_SELECT_KEY). It must be used inside a component tree where provideSelection() was called by the parent table.', NULL, NULL, NULL, '{"consumedInterfaces": ["IDataTableProvideSelection", "IDataTableSelectableItem", "IDataTableSelectProps"]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('624fec14-1e72-431a-bae8-9602e852ecfe', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'composable', 'use-select-link', 'useSelectLink', NULL, 'Commons', 'mdi-link-variant', '', 'Bridges a router link and a group selection: when the link becomes active (current route matches), it automatically selects its group item. Used internally by navigation components (NavList, BottomNav, Tabs) so that a hard navigation or a programmatic router push keeps the selected state in sync without a manual v-model update.', NULL, 'function useSelectLink(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('59a412a2-d07e-4c0a-ad54-daacfed88728', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'composable', 'use-sheet-swipe', 'useSheetSwipe', NULL, 'Sheet', 'mdi-gesture-swipe-up', '', 'Encapsulates bottom-sheet swipe gesture logic using Pointer Events (covers both mouse and touch). Tracks pointerdown → pointermove → pointerup on a dedicated handle element, resolves the target snap point on release via velocity (fast flick = step one snap) or absolute distance (slow drag = nearest snap), and exposes reactive drag state for 1:1 finger tracking during the gesture.', NULL, 'function useSheetSwipe(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('9e553650-4330-4dae-b8a0-ab826a339697', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'composable', 'use-size', 'useSize', NULL, 'Commons', 'mdi-magnify-plus-outline', '', 'Resolves the `size` prop to component-local modifier classes and optional width/height inline styles. Named presets (x-small/small/default/large/x-large) emit BEM modifier classes; custom values emit pixel dimensions.', NULL, 'function useSize(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('efd67f4a-2a94-44b9-915a-15f0619e1218', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'composable', 'use-slider-field', 'useSteps', NULL, 'SliderField', 'mdi-tune-variant', '', 'Pure-function stepping math for OrigamSliderField. Computes reactive min / max / step / decimals values from the component props and exposes a roundValue helper that snaps any raw number to the nearest valid step (clamped to [min, max]). After the migration to a native <input type="range">, this is the only remaining logic layer for the slider — the browser now owns drag tracking.', NULL, 'function useSteps(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('3c9573ff-184e-47b9-8d46-715cd26965b5', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'composable', 'use-snackbar', 'useCountdown', NULL, 'Snackbar', 'mdi-timer-sand', '', 'Internal countdown timer used by OrigamSnackbar to drive the auto-dismiss progress indicator. Counts down from a given millisecond value using setInterval, ticking at the CSS transition duration of the host element so the progress bar remains visually synchronised. Exposes clear / reset / start controls and a reactive time ref.', NULL, 'function useCountdown(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('650ee29b-d5bd-4ebe-ab7f-59dc9b16d262', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'composable', 'use-snackbar-group', 'useSnackbarGroup', NULL, 'Snackbar', 'mdi-bell-outline', '', 'Module-level singleton store for a named snackbar stack. Push notifications via notify(), dismiss them by id or all at once. Each call sharing the same id option reads and writes the same reactive items list — the composable and the matching <OrigamSnackbarGroup id="…"> component share live state with no event bus required.', NULL, 'function useSnackbarGroup(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('7390e4ba-3b43-407b-a7fe-0de5664a489d', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'composable', 'use-snackbar-group-internal', 'useSnackbarGroupInternal', 'Snackbar', 'Snackbar', NULL, NULL, NULL, NULL, 'function useSnackbarGroupInternal(id?: MaybeRefOrGetter<string> = SNACKBAR_GROUP_DEFAULT_ID): { rawItems: ComputedRef<ISnackbarGroupItem[]>; itemCount: ComputedRef<number>; registerDefaultDuration: (duration: number) => void; }', NULL, NULL, 'packages/ds/src/composables/Snackbar/snackbarGroupInternal.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('26059c27-9335-448e-a83f-466f2c74e4c6', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'composable', 'use-sort', 'useSort', NULL, 'DataTable', 'mdi-sort', '', 'Inject accessor for the sort context provided by provideSort inside OrigamDataTable. Returns the reactive sortBy array and the toggleSort / isSorted helpers. Used by header cells to read and update the active sort columns. The companion useSortedItems applies the sort order to a reactive item list.', NULL, 'function useSort(): IDataTableProvideSort
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('5cdfb335-85f4-4fca-9165-46f552abdf79', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'composable', 'use-sorted-items', 'useSortedItems', 'DataTable', 'DataTable', NULL, NULL, NULL, NULL, 'function useSortedItems(props: { customKeySort: TDataTableCompareFunction | undefined }, items: Ref<T[]>, sortBy: Ref<Array<IDataTableSortItem>>, options?: { transform?: (item: T) => Record<string, unknown> sortFunctions?: Ref<Record<string, TDataTableCompareFunction> | undefined> sortRawFunctions?: Ref<Record<string, TDataTableCompareFunction> | undefined> }): { sortedItems: ComputedRef<T[]>; }', NULL, NULL, 'packages/ds/src/composables/DataTable/sortedItems.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('70c5573d-90e2-4790-9e73-629632f2cae9', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'composable', 'use-ssr-boot', 'useSsrBoot', NULL, 'Commons', 'mdi-server', '', 'Defers CSS transitions until after the first browser paint to prevent flash-of-transition on SSR hydration. Returns an isBooted flag (false during SSR and the first rAF frame, then true) and a ssrBootStyles computed that injects `transition: none !important` while booting, suppressing unwanted entry animations during hydration.', NULL, 'function useSsrBoot(): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('37c11900-85bf-4968-951f-7beadd5a35af', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'composable', 'use-stack', 'useStack', NULL, 'Commons', 'mdi-layers-outline', '', 'Manages z-index stacking order for overlay components (Dialog, Menu, Tooltip, Drawer, …). Registers the component in the global GLOBAL_STACK array when it becomes active and auto-computes a z-index 10 units above the current topmost overlay. Exposes globalTop (is this the topmost overlay worldwide?) and localTop (does this overlay have no active child overlays?) for pointer-event and close-on-outside-click decisions.', NULL, 'function useStack(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('9e146d0f-e06e-481c-b25c-6c3578883845', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'composable', 'use-state-effect', 'useStateEffect', NULL, 'Commons', 'mdi-palette-swatch-variant', '', 'Unified composable that consolidates eight visual axes (color, bgColor, border, rounded, elevation, padding, margin, gap) into a single state-aware layer. Reads the hover / active state and their override objects (IHoverState / IActiveState) and emits per-axis classes + styles for each axis. Replaces the prior chain of useColorEffect + useBorder + useRounded + useElevation + usePadding + useMargin that every visual component had to repeat.', NULL, 'function useStateEffect(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('a495255b-f696-4a4d-b871-fccd47819480', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'composable', 'use-state-flag', 'useStateFlag', 'Commons', 'Commons', NULL, NULL, NULL, NULL, 'function useStateFlag(props: object, options: IStateFlagOptions<S>): IStateFlagReturn', NULL, NULL, 'packages/ds/src/composables/Commons/stateFlag.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
