INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('62813ba4-d049-461f-8d36-f02c5ade7f77', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'const', 'chart-annotation-arrowhead-min-size', 'CHART_ANNOTATION_ARROWHEAD_MIN_SIZE', 'Chart', NULL, NULL, NULL, NULL, 'export const CHART_ANNOTATION_ARROWHEAD_MIN_SIZE = 6', NULL, NULL, '6', 'packages/ds/src/consts/Chart/chart.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('59022107-17d3-4dfb-9b88-065f1e3a75d1', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'composable', 'use-status', 'useStatus', NULL, 'Commons', 'mdi-alert-circle-outline', '', 'Resolves semantic status props (success, info, warning, error) into icon slots, status classes, and a forced intent color. The status intent overrides any color / bgColor the consumer passed — a status colour is non-negotiable by design. Also manages icon routing across prepend / append / replace slots based on statusIconPosition.', NULL, 'function useStatus(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('c2ba38b1-e12b-40ce-a7dd-9bf516bc2d95', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'composable', 'use-sticky', 'useSticky', NULL, 'Commons', 'mdi-pin-outline', '', 'Implements the "sticky-while-scrolling" pattern for taller-than-viewport navigation drawers. Tracks scroll direction and element bounding rect to decide whether the sidebar is stuck at the top, stuck at the bottom, or free-floating mid-page. Returns stickyStyles with the appropriate top/bottom offset so the sidebar scrolls naturally through long content without jumping.', NULL, 'function useSticky(options: ISticky): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('13315667-b8ee-409c-9d5e-d91b46634d15', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'composable', 'use-style', 'useStyle', NULL, 'Commons', 'mdi-code-tags', '', 'Injects a dynamic <style> tag into document.head scoped to a generated element id, allowing components to apply per-instance CSS that cannot be expressed as inline styles (e.g. pseudo-element rules, :hover selectors, @keyframes). Also exposes the lower-level useStyleTag for raw CSS string injection. Both composables manage their own lifecycle: they load on mount and unload on scope dispose.', NULL, 'function useStyle(
