INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('34c60917-db99-4488-aa1f-2c507b50e466', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'composable', 'use-teleport', 'useTeleport', NULL, 'Commons', 'mdi-arrow-top-right-bold-box-outline', '', 'Resolves the Vue Teleport target for overlay components. Accepts true (disable teleport — render inline), false (teleport to document.body), a CSS selector string (teleport to the matched element), or a raw Element. Creates an .origam-overlay-container div inside the target when one does not already exist, so multiple overlays sharing the same target stack correctly without polluting the host''s direct children.', NULL, 'function useTeleport(
