INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('71646374-3040-45dd-9705-62662f386719', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'composable', 'use-text-color', 'useTextColor', NULL, 'Commons', 'mdi-format-color-text', '', 'Foreground-only color helper. Resolves the `color` prop to a utility class (`origam--color-*`) for tokenised intents, or to an inline `color:` declaration for raw CSS values and gradients.', NULL, 'function useTextColor<T extends Record<K, TColor>, K extends string>(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('653b99ed-d240-4185-9d40-eeb066fd14aa', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'composable', 'use-theme', 'useTheme', NULL, 'Theme', 'mdi-theme-light-dark', '', 'Module-level singleton managing the brand theme axis (data-theme attribute) and the color-mode axis (data-mode attribute). Persists both axes to localStorage and reacts to prefers-color-scheme. Every call to useTheme() shares the same refs.', NULL, 'function useTheme(): {
