INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('cc6efd7b-9a6b-4d7f-bdbe-8afee30ea632', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'composable', 'use-toggle-scope', 'useToggleScope', NULL, 'Commons', 'mdi-toggle-switch-outline', '', 'Conditionally activates a Vue effectScope driven by a reactive boolean source. When the source turns true the scope starts (running the provided callback inside it); when it turns false the scope is stopped and discarded. The scope is also stopped on parent scope dispose.', NULL, 'function useToggleScope(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('1dba4d88-0790-4d59-aaee-6320ee8a4a05', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'composable', 'use-touch', 'useTouch', NULL, 'Commons', 'mdi-gesture-swipe', '', 'Enables swipe-to-open / swipe-to-close gesture handling for drawer-like components. Listens to touchstart / touchmove / touchend on window, computes drag progress relative to a positioned edge (left, right, top, bottom), and resolves the gesture via velocity-based fling detection using useVelocity.', NULL, 'function useTouch(options: {
