INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('41f1f9b5-931e-41c5-8252-4ffe4a501496', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'composable', 'use-velocity', 'useVelocity', NULL, 'Commons', 'mdi-speedometer', '', 'Tracks touch-event samples per finger (identified by touch.identifier) in circular buffers and computes the instantaneous velocity vector at touchend via impulse-velocity analysis. Used by useTouch to decide whether a fling gesture is fast enough to open or close a drawer.', NULL, 'function useVelocity(): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('fb770e5e-9cc1-416a-8cde-cce8e34b0b35', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'composable', 'use-video-player', 'useVideoPlayer', NULL, 'Video', 'mdi-video-outline', '', 'Headless video player composable. Composes the media-shared useMediaPlayer base and adds video-only state (fullscreen, pip) plus methods (enterFullscreen, exitFullscreen, toggleFullscreen, requestPip, exitPip, togglePip). Handles the iOS Safari webkitEnterFullscreen fallback and the document-level fullscreenchange listener.', NULL, 'function useVideoPlayer(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('d2386caa-a644-4e8b-8c6b-46d46b94efe3', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'composable', 'use-virtual', 'useVirtual', NULL, 'Commons', 'mdi-view-list-outline', '', 'Virtual-scroll engine for large datasets. Maintains a dynamic window of visible items, computes per-item offsets via a debounced binary-search algorithm, tracks scroll velocity for predictive buffering, and exposes scrollToIndex with optional animated scrolling through useGoTo. SSR-safe — all DOM access is guarded.', NULL, 'function useVirtual<T>(
