INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('29ed2b7c-cc77-403c-8d74-48aeef1d6e44', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'interface', 'i-chart-sankey-link', 'IChartSankeyLink', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_sankey_link.description', 'Internal link descriptor for each IChartSankeyDatum after Sankey layout. Carries the rendered SVG cubic Bezier path d attribute, visual metadata and resolved colour. Produced by the Sankey layout engine — not intended for direct consumer use.', 'export interface IChartSankeyLink {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('f6e66fdb-5ca8-4b55-a35a-725270d541ea', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'interface', 'i-chart-sankey-node', 'IChartSankeyNode', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_sankey_node.description', 'Internal node descriptor produced by the Sankey layout engine. All coordinates are in SVG-user-unit space. Nodes are inferred from the union of all from and to strings in IChartSankeyDatum; column is assigned by topological depth (Kahn''s algorithm).', 'export interface IChartSankeyNode {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('e30426bb-2f8b-42d9-bd5c-a8a90bce9533', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'interface', 'i-chart-sparkline-emits', 'IChartSparklineEmits', 'Data Visualisation', NULL, NULL, 'interfaces.catalog.i_chart_sparkline_emits.description', 'Emits surfaced by OrigamChartSparkline. Single event — point-click — fired on mouse click or keyboard activation on a data point, providing the IChartPoint payload and the originating DOM event.', 'export interface IChartSparklineEmits {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('4dc40d74-b658-4cf7-9976-460f73ebb198', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'interface', 'i-chart-sankey-props', 'IChartSankeyProps', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_sankey_props.description', 'Props for <OrigamChartSankey>. The component consumes series[0] only — each item in series[0].data must conform to IChartSankeyDatum ({ from, to, value }). Nodes are inferred automatically; columns are assigned by topological depth. Extends IChartBaseProps.', 'export interface IChartSankeyProps extends IChartBaseProps {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('8aa6a824-52f6-4340-a836-30420e232a8c', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'interface', 'i-chart-sankey-slots', 'IChartSankeySlots', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_sankey_slots.description', 'Slot signatures exposed by <OrigamChartSankey>. Extends IChartBaseSlots with a node-label slot that replaces the label rendered beside each node, receiving the node name, value, formatted value, resolved colour and column index.', 'export interface IChartSankeySlots extends IChartBaseSlots {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('fa40b5bf-f319-4c88-982c-e771a2f9a352', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'interface', 'i-chart-scales', 'IChartScales', 'Data Visualisation', NULL, NULL, 'interfaces.catalog.i_chart_scales.description', 'Pair of pixel-mapping functions produced by useChart from the data range and viewBox size. Pure functions — safe to call from computed refs. x maps a value or category index to an SVG horizontal coordinate; y maps a numeric value to an SVG vertical coordinate.', 'export interface IChartScales {
