    (e: ''quality-change'', quality: string): void
    (e: ''download''): void
    (e: ''previous''): void
    (e: ''next''): void
    (e: ''update:loopMode'', mode: TAudioLoopMode): void
    (e: ''update:shuffle'', shuffle: boolean): void
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('cc58465e-363f-4b2b-ad28-bfd93f5db253', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'interface', 'i-media-controller-props', 'IMediaControllerProps', 'Component Props', NULL, NULL, 'interfaces.catalog.i_media_controller_props.description', 'Props for <OrigamMediaController> — the universal media-controls shell consumed by <OrigamVideo> and <OrigamAudio>. Purely presentational: it receives state and methods from the parent and emits intents back. Audio-specific controls (loop, shuffle, prev/next) are opt-in so video consumers see zero regression.', 'export interface IMediaControllerProps extends ICommonsComponentProps {
