INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a945ee86-a4ee-4a9b-a7eb-0b397530cfb3', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '60fef607-f567-4aef-8446-1de74a84a27b', 'props', 'IActivatorProps', true, NULL, '', 'Props controlling how the overlay is triggered. Includes activator selector/element, open-on strategy (click, hover, focus, context-menu), close-on-content-click, delay settings inherited from IDelayProps, and an optional target override.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3c7b1aab-433d-4c9d-8ec4-504f9fc4e5b8', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '60fef607-f567-4aef-8446-1de74a84a27b', 'isActive', 'Ref<boolean>', true, NULL, '', 'Reactive flag representing the open/closed state of the overlay. useActivator reads and writes this ref to toggle the overlay on user interaction.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0968b5c9-310c-490f-96d3-5646248f3a2d', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '60fef607-f567-4aef-8446-1de74a84a27b', 'isTop', 'Ref<boolean>', true, NULL, '', 'Reactive flag set by the overlay stack manager. When true, this overlay is the topmost one; when it becomes false while hover/focus-triggered, the composable auto-closes the overlay.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0fd9bce3-7fb3-4f20-8572-74c3afdc4c61', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'ce810502-5c08-4232-aaa5-261c5eefa289', 'props', 'IActiveProps & Record<string, any>', true, NULL, '', 'Component props. Reads `props[prop]` (default: `props.active`).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2d2287fe-e0f9-4210-980d-a15639baf661', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'ce810502-5c08-4232-aaa5-261c5eefa289', 'prop', 'string', false, '''active''', '', 'The prop key to read for the active value. Use "modelValue" for components with a v-model binding.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fd5c7219-0b73-4234-8163-8fa8c16a2c61', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'ce810502-5c08-4232-aaa5-261c5eefa289', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for the `{name}--active` class.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7cba7074-eb25-4107-9242-9d013997ccb0', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '7d5b10da-71fc-4d34-aee8-88ca7a7e4cad', 'props', 'IAdjacentProps', true, NULL, '', 'Props carrying prependIcon, appendIcon, prependAvatar, and appendAvatar values. The composable reads these to determine whether the outer prepend/append regions should render.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5436cc06-e7ea-4267-83ab-d6228092c262', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '7d5b10da-71fc-4d34-aee8-88ca7a7e4cad', 'prependIcon', 'Ref | ComputedRef', false, NULL, '', 'Optional reactive icon override for the prepend slot. When provided, takes precedence over props.prependIcon, enabling status-aware icon swapping without prop mutation.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('04ded426-7e09-450b-b246-5349a7fa0fb5', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '7d5b10da-71fc-4d34-aee8-88ca7a7e4cad', 'appendIcon', 'Ref | ComputedRef', false, NULL, '', 'Optional reactive icon override for the append slot. Same semantics as prependIcon but for the trailing position.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('37600938-03d4-46a8-920e-8e9674d7e755', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '3ce0c5eb-fc3d-4910-85e3-1892590076dd', 'props', 'IAdjacentInnerProps', true, NULL, NULL, NULL, 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0af771bc-2110-4915-a74a-dd0891dc8a27', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '13bcf221-480e-4fd4-8a5f-e81e18e18639', 'props', '{ aspectRatio?: string | number }', true, NULL, '', 'Object carrying an optional aspectRatio value. Accepts a numeric ratio (1.777 for 16:9), a division expression string ("16/9"), or is left undefined to use window.innerWidth / window.innerHeight as the ratio.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e4c024a5-6f62-453f-8641-6c9065122476', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'c9d0b0bd-6c9c-4847-94d0-0549a9b75404', 'props', 'IUseAudioProps', true, NULL, '', 'Props object with audio (URL of the audio source) and playAudio (boolean flag). When playAudio changes to true the composable calls onPlay(); when it changes to false it calls onStop(). When audio changes, wasPlayed and isPlaying are reset.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('61c60b7f-0110-4428-9562-0e537031839c', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '80d23a58-300d-4f83-b244-20511c394c24', 'options', 'IUseOrigamAudioPlayerOptions', false, '{}', '', 'Optional configuration. Accepts `audioRef` (bring your own ref), `autoplay`, `muted`, `loop`, and `preload`. All fields are optional.', 0, false, NULL, NULL);
