INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4506bcf7-2183-43a8-b73e-a040544a90a0', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'b1c5157a-6237-4d52-98b1-0eb0cab45f3e', 'options', 'IUseCalendarOptions', true, NULL, '', 'Configuration thunks. All fields are getter functions so the composable reacts to reactive sources without re-instantiation. Includes events, view, currentDate, firstDayOfWeek, slotDuration, dayStartHour, dayEndHour, and optional minDate/maxDate/locale.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0c0eb076-c56e-4a71-8a49-cee43c0e638b', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'b1c5157a-6237-4d52-98b1-0eb0cab45f3e', 'setView', '(view: TCalendarView) => void', false, NULL, '', 'Optional callback invoked by the returned setView proxy. Bind to a v-model:view setter to keep the parent state in sync when the calendar switches views.', 1, false, NULL, NULL);
