INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('367b2761-a3ef-436e-8639-fa5cf7ceb323', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '37c11900-85bf-4968-951f-7beadd5a35af', 'disableGlobalStack', 'Readonly<Ref<boolean>>', true, NULL, '', 'When true, skips registration in GLOBAL_STACK. Use for overlays that manage their own z-index independently (e.g. nested teleport roots) and should not compete with the global stacking order.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6732829c-d4c8-4767-9bbd-62f34a791a3d', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '9e146d0f-e06e-481c-b25c-6c3578883845', 'props', 'TStateEffectProps', true, NULL, '', 'Component props implementing all eight axes: IColorProps & IBgColorProps & IBorderProps & IRoundedProps & IElevationProps & IPaddingProps & IMarginProps & { gap? }. Also reads props.status when present to force the matching semantic intent (overrides color/bgColor).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7bdbcc61-2866-4699-9bb8-cda5d88634ce', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '9e146d0f-e06e-481c-b25c-6c3578883845', 'isHover', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'Reactive hover state from useHover. When true, the composable applies the override values from hoverState for each axis.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3cdc9012-4564-46fa-94c7-950e3920d602', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '9e146d0f-e06e-481c-b25c-6c3578883845', 'isActive', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'Reactive active/selected state from useActive. When true (and isHover is false), override values from activeState are applied. Hover takes priority when both are engaged simultaneously.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d4cccf59-edfa-47d9-99bf-01d8302af8f9', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '9e146d0f-e06e-481c-b25c-6c3578883845', 'hoverState', 'ComputedRef<IHoverState | undefined>', false, 'computed(() => undefined)', '', 'State config object from useHover. Contains per-axis override values (color, bgColor, border, rounded, elevation, padding, margin, gap) to apply while hovered.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d5783682-2259-470d-b0b1-c10f750a9a59', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '9e146d0f-e06e-481c-b25c-6c3578883845', 'activeState', 'ComputedRef<IActiveState | undefined>', false, 'computed(() => undefined)', '', 'State config object from useActive. Same shape as IHoverState — per-axis overrides applied while the item is selected/active.', 4, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('65500ec6-5d9e-465d-accc-28ff2776120d', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '9e146d0f-e06e-481c-b25c-6c3578883845', 'isDisabled', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'When true, colorClasses is emptied (utility classes suppressed) so the disabled opacity veil is not overridden by a tokenised background.', 5, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1c26644e-b2e8-4998-ab61-9fdf735fd249', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '9e146d0f-e06e-481c-b25c-6c3578883845', 'flat', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'When true, elevationClasses and elevationStyles resolve to empty. Bridges the flat prop of Btn / Card without requiring a separate useElevation call.', 6, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('06cfcc78-5216-4258-8784-aeb4e8acae2b', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'a495255b-f696-4a4d-b871-fccd47819480', 'props', 'object', true, NULL, NULL, NULL, 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1c3532e3-28a7-4627-9174-3d0fa51041b0', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'a495255b-f696-4a4d-b871-fccd47819480', 'options', 'IStateFlagOptions<S>', true, NULL, NULL, NULL, 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('519d4bed-0006-408c-a105-d29cd8683c66', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '59022107-17d3-4dfb-9b88-065f1e3a75d1', 'props', 'IStatusProps & IAdjacentProps', true, NULL, '', 'Component props. Reads status (TStatus: success | info | warning | error), statusIconPosition (prepend | append | both | replace), prependIcon, appendIcon, and icon. When status is set and statusIconPosition is replace, the status icon overwrites props.icon; when prepend/append/both, it fills the matching slot only if no explicit icon prop was passed.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2eed026e-8384-4a46-8ce8-6695a0e54446', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '59022107-17d3-4dfb-9b88-065f1e3a75d1', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name used to build the BEM modifier class `{name}--{status}` (e.g. origam-alert--success). Defaults to the current Vue instance name.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('63e71dec-9846-4958-8328-70a83b2a553a', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'c2ba38b1-e12b-40ce-a7dd-9bf516bc2d95', 'rootEl', 'Ref<HTMLElement | undefined>', true, NULL, NULL, NULL, 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4285c5ff-050c-4280-ae1b-6e708e19e36e', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'c2ba38b1-e12b-40ce-a7dd-9bf516bc2d95', 'isSticky', 'Ref<boolean>', true, NULL, NULL, NULL, 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1c5acf9c-bbb5-4598-abb4-2385a57f2d19', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'c2ba38b1-e12b-40ce-a7dd-9bf516bc2d95', 'layoutItemStyles', 'Ref<CSSProperties>', true, NULL, NULL, NULL, 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3ed9847c-f4b7-4f1b-9333-9afd7ae7a7f1', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '13315667-b8ee-409c-9d5e-d91b46634d15', 'styles', 'ComputedRef', true, NULL, '', 'A ComputedRef returning a CSS value array or object. Accepts the same formats as Vue :style bindings (array of objects, strings, or mixed). useStyle normalises this to a flat `#id { prop: value; … }` string and feeds it to useStyleTag.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fac5d25c-c02c-478c-907b-6d6574a379f1', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '13315667-b8ee-409c-9d5e-d91b46634d15', 'uniq', 'MaybeRefOrGetter<string | undefined>', false, 'undefined', '', 'Optional fixed element id. When omitted, a unique id is generated from the component name and a counter (e.g. origam-card-3). Provide a fixed id when multiple instances must share the same <style> tag (e.g. global animation keyframes).', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('10874cad-8a76-49d0-93d7-37dfbdf45844', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '13315667-b8ee-409c-9d5e-d91b46634d15', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for the generated id. Defaults to the current Vue instance name.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('17d3cdcc-1002-4950-a110-34a407946122', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '607f761d-5bc6-42df-b3be-71f1aa280c11', 'css', 'MaybeRef<string>', true, NULL, NULL, NULL, 0, false, NULL, NULL);
