INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3c763e58-4d61-4b93-86dc-584291071afc', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '34c60917-db99-4488-aa1f-2c507b50e466', 'target', 'Ref<boolean | string | Element>', true, NULL, '', 'Reactive teleport destination. true → returns undefined (Vue Teleport disabled, renders in-place). false → document.body. A CSS selector string → querySelector result. An Element → used directly. Returns undefined and warns if a string selector yields no match.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7a57c7c9-39cc-4587-b512-1144a43bee1c', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '35a3e0ad-0aad-4685-8fe7-8d47765ac71f', 'fieldRef', 'Ref<{ $el?: HTMLElement } | undefined>', true, NULL, NULL, NULL, 0, false, NULL, NULL);
