INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cec7acc9-5934-47c0-b19e-f2470dc76064', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '43ec7313-8e60-4bd5-b26c-2f6deb144127', 'options', 'IUseTextareaRichOptions', true, NULL, NULL, NULL, 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d47ebff2-f22c-41e1-92b8-ffd038b9662b', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '409063cf-6f33-4ea0-a49e-8acf1d2cb586', 'options', 'IUseTextareaRichOptions', true, NULL, '', 'Configuration object. value: () => string — getter for the initial HTML content (bound to the parent v-model). onUpdate: (html: string) => void — called with sanitised HTML on every change. onFormat: (command, value?) => void — called after each format command (lets the host open a link popover on Cmd+K). disabled: () => boolean — suppresses all commands and keyboard shortcuts when true.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('aa9329d6-2100-40b6-ab26-ca663309850d', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '71646374-3040-45dd-9705-62662f386719', 'props', 'T | Ref<TColor>', true, NULL, '', 'Either the component props object (paired with `name`) or a plain Ref<TColor>.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6bc64342-faf5-47d8-9477-278ee94a6ea8', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '71646374-3040-45dd-9705-62662f386719', 'name', 'K', false, NULL, '', 'The key to read from the props object. Typically "color". Omit when passing a plain Ref.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b2548e74-1a18-416c-8b25-06dc5a6890f0', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '61c7c6e9-2411-4b31-b384-0854d8326713', 'fn', '(...args: T) => R', true, NULL, '', 'The function to throttle. Called immediately on the first invocation within each window. The return value is discarded — the wrapper always returns void.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f113d151-a10c-4e08-8352-0be9b816d2df', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '61c7c6e9-2411-4b31-b384-0854d8326713', 'wait', 'number', true, NULL, '', 'Throttle window in milliseconds. No call will execute within wait ms of the previous execution.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('dc47e44d-b629-4776-b82f-6d79630c15ab', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'cc6efd7b-9a6b-4d7f-bdbe-8afee30ea632', 'source', 'WatchSource<boolean>', true, NULL, '', 'Reactive boolean source (ref, computed, or getter). When it evaluates to true the scope is started; when false the scope is stopped.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9b6bd54f-7417-4410-a851-595ecd3fbae4', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'cc6efd7b-9a6b-4d7f-bdbe-8afee30ea632', 'fn', '(reset: () => void) => void', true, NULL, '', 'Callback run inside the new effectScope. Receives a `reset()` function that can be called from inside the scope to stop the current scope and immediately restart it — useful for subscriptions that need to re-initialise when an inner condition changes.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('33a14889-7f61-4c85-8d7f-6d2fbd16dfee', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '1dba4d88-0790-4d59-aaee-6320ee8a4a05', 'isActive', 'Ref<boolean>', true, NULL, '', 'Whether the drawer is currently open. The composable writes to this ref when a fling gesture settles.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d9939faa-a3fa-40ba-9b71-cbdb1754c989', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '1dba4d88-0790-4d59-aaee-6320ee8a4a05', 'isTemporary', 'Ref<boolean>', true, NULL, '', 'When true the drawer is temporary (modal overlay). The touch zone logic also activates for touches anywhere inside the element body, not only at the edge.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6306a501-ed60-4af0-9a35-20a4f150b3f9', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '1dba4d88-0790-4d59-aaee-6320ee8a4a05', 'width', 'Ref<number>', true, NULL, '', 'Pixel width (or height for top/bottom positions) of the drawer. Used to compute drag progress as a fraction in [0, 1].', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9612d7f7-8cf1-45f4-b768-22b758ce3188', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '1dba4d88-0790-4d59-aaee-6320ee8a4a05', 'touchless', 'Ref<boolean>', true, NULL, '', 'When true all touch handling is disabled. Lets the consumer disable swipe gestures without unmounting the composable.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('666760e1-bd26-4353-99cc-58b6f84cfb54', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '1dba4d88-0790-4d59-aaee-6320ee8a4a05', 'position', 'Ref<''left'' | ''right'' | ''top'' | ''bottom''>', true, NULL, '', 'The edge from which the drawer slides in. Determines the touch zone, coordinate axis, and transform direction.', 4, false, NULL, NULL);
