INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('16455603-cc0a-425b-8ef8-55f65e36235e', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'd2386caa-a644-4e8b-8c6b-46d46b94efe3', 'props', 'IVirtualProps', true, NULL, '', 'Reads `itemHeight` (expected row height in px, used to estimate the initial window), `height` (container height as string / number), `scrollDuration` (ms, default 300), `scrollEasing` (easing name, default easeInOutCubic).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ea7c3bdf-346d-4870-9323-036d8afc0581', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'd2386caa-a644-4e8b-8c6b-46d46b94efe3', 'items', 'Ref<readonly T[]>', true, NULL, '', 'The full dataset ref. The composable slices this array to produce `computedItems`. Changing the ref triggers an offset recalculation.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1589c53f-4f89-46eb-9d2b-ba54713ad051', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '2589bf3e-1f68-43aa-98d6-75fa7c7c7771', 'props', 'Props', true, NULL, '', 'The component props object returned by defineProps. The composable reads `props[prop]` and inspects `vm.vnode.props` to detect whether the listener is wired.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0f65290b-7e3a-4e11-a864-271a62318415', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '2589bf3e-1f68-43aa-98d6-75fa7c7c7771', 'prop', 'Prop', true, NULL, '', 'The prop key to observe, e.g. `"modelValue"` for a standard v-model binding.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a37cccdc-1285-4533-b660-4bff43f88cd2', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '2589bf3e-1f68-43aa-98d6-75fa7c7c7771', 'defaultValue', 'MaybeRefOrGetter<Props[Prop] | undefined>', false, NULL, '', 'Value used to initialise the internal ref when the prop is undefined on first render.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7989643d-9f29-4500-8f46-1124cc38abe4', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '2589bf3e-1f68-43aa-98d6-75fa7c7c7771', 'transformIn', '(value?: Props[Prop]) => Inner', false, '(v?: Props[Prop]) => v as Inner', '', 'Optional transform applied to the external prop value before exposing it to the component. Useful for converting a string to a number, or normalising null / undefined.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7daf4fdc-fd15-4e56-8aed-5371fd94bc31', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '2589bf3e-1f68-43aa-98d6-75fa7c7c7771', 'transformOut', '(value: Inner) => Props[Prop]', false, '(v: Inner) => v as Props[Prop]', '', 'Optional inverse transform applied before emitting `update:prop`. Pairs with transformIn to keep the internal representation separate from the public API value.', 4, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cb65dc8c-d6b3-43c2-bd31-3b203ef7353d', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '69863aa2-1c82-4927-86c7-5beac820d1de', 'options', 'MaybeRefOrGetter<IUseWatermarkOptions>', false, '{}', '', 'Options bag (static object, reactive ref, or getter function). Reads: `text`, `image` (URL), `opacity` (default 0.15), `angle` (degrees, default -30), `gap` (tile spacing in px, default 100), `fontSize` (px, default 16), `fontFamily`, `color`, `fontWeight`, `pointerEvents` ("none" | "auto"), `zIndex`, `antiTamper` (enable MutationObserver re-injection). Passing a ref makes patternUrl update reactively when options change.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('dc9fd4fa-8cd8-4702-b95d-00a04e873c3d', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '6133b967-f83f-43a7-8b25-aabf2b9c1800', 'srcRef', 'Ref<string | undefined | null>', true, NULL, '', 'Reactive reference to the audio file URL. The composable watches this ref and re-triggers computation whenever the value changes. null / undefined clears the peaks array.', 0, false, NULL, NULL);
