INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('eb223eaf-294f-42d8-ab06-013167fadf88', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', 'a8fc30f9-94ec-4247-aae1-3709ebdacb89', 'viewportMargin', 'number', NULL, NULL, true, NULL, '12', NULL, 'Minimum breathing room in pixels between the floating content and each viewport edge. Defaults to 12 so panels never overlap browser chrome.', 4, false, NULL, NULL);
