INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7258dba2-f9db-45d0-9a3c-5396927b2c3c', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', '71a1da39-1db1-4d01-b9e1-e227d24da0c2', 'lang', 'TCodeLangOpen', 'code-lang', 'type', NULL, false, '''plaintext''', 'components.code.props.lang.description', 'Language grammar to apply. Supported: ''plaintext'' | ''vue'' | ''ts'' | ''js'' | ''tsx'' | ''jsx'' | ''scss'' | ''css'' | ''json'' | ''bash'' | ''html'' | ''xml'' | ''yaml'' | ''md''. Unknown values fall back to plaintext.', 1, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a9ac1f50-4810-475a-a9f1-50c082323248', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', '71a1da39-1db1-4d01-b9e1-e227d24da0c2', 'lineNumbers', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.line_numbers.description', 'Shows a left gutter with line numbers. Pure CSS counter — no JS layout work.', 2, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('226d08f0-33a5-4daa-816e-303000abaf97', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', '71a1da39-1db1-4d01-b9e1-e227d24da0c2', 'highlightLines', 'number[] | string | null', '', 'primitive', NULL, false, 'null', 'components.code.props.highlight_lines.description', 'Lines to highlight. Accepts a 1-based array ([2, 5, 6]) or a range string (''2,5-7''). Null/empty disables.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fbe620f5-d7a5-4979-9826-2db352e81c52', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', '71a1da39-1db1-4d01-b9e1-e227d24da0c2', 'copyable', 'boolean', '', 'primitive', NULL, false, 'true', 'components.code.props.copyable.description', 'Shows the copy-to-clipboard button. True by default — most code blocks benefit from it.', 4, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('477aefed-573a-4b6b-bd24-f0fe169155cf', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', '71a1da39-1db1-4d01-b9e1-e227d24da0c2', 'format', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.format.description', 'Auto-format the code before highlighting. Reserved — currently a no-op that warns in dev mode. Prettier is not bundled at runtime to keep the tarball small.', 5, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('16838efe-2bd1-4491-9649-5a70a4497d7c', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', '71a1da39-1db1-4d01-b9e1-e227d24da0c2', 'wrap', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.wrap.description', 'Wraps long lines instead of scrolling horizontally.', 6, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5a4f06c2-ca35-412f-8330-c5ba47293f94', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', '71a1da39-1db1-4d01-b9e1-e227d24da0c2', 'filename', 'string', '', 'primitive', NULL, false, 'undefined', 'components.code.props.filename.description', 'Optional filename rendered in the header bar (e.g. ''App.vue''). When present AND copyable=true, the header hosts the copy button; otherwise the copy button floats in the top-right corner.', 7, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('34b0c81e-4c04-48f7-b4e9-baf35dc3665c', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', '71a1da39-1db1-4d01-b9e1-e227d24da0c2', 'compact', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.compact.description', 'Renders as a single-line inline pill (ideal for install commands). Header, filename and line numbers are suppressed; the copy button collapses to a small icon.', 8, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b1fc40fb-9e63-41d8-b784-78629a07521e', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', '71a1da39-1db1-4d01-b9e1-e227d24da0c2', 'prompt', 'string', '', 'primitive', NULL, false, 'undefined', 'components.code.props.prompt.description', 'Decorative prefix rendered before the code (e.g. ''$'' for shell commands). Purely visual — not copied to clipboard.', 9, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('55fdc7a0-659d-4375-be33-c7f49074e6d8', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', '71a1da39-1db1-4d01-b9e1-e227d24da0c2', 'hideHeader', 'boolean', NULL, NULL, NULL, false, NULL, NULL, 'Do not render the header bar (filename / language badge / copy button). For a block embedded in a surface that already shows that information, such as a tab of OrigamCodeGroup.', 10, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2fb9c1a1-d6e6-42c6-9a27-539b24cf9a62', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', '71a1da39-1db1-4d01-b9e1-e227d24da0c2', 'flat', 'boolean', NULL, NULL, NULL, false, NULL, NULL, 'Flatten the block into its host: no border, no radius, no elevation, no outer margin.', 11, false, NULL, NULL);
