INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8a984173-5fa1-4bab-ab2c-3306a435cf46', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', 'a74ac73e-c29d-47d0-8c34-9926c717bdac', 'state', 'IMediaPlayerState', '', 'primitive', NULL, true, '—', 'components.media_controller.props.state.description', 'Reactive media state from useMediaPlayer() (or a specialisation: useVideoPlayer, useAudioPlayer). Contains refs for playing, currentTime, duration, volume, muted, buffered, playbackRate, remoteAvailable, remoteState.', 0, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('012f28e7-8286-4c0e-ba20-144750d081da', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', 'a74ac73e-c29d-47d0-8c34-9926c717bdac', 'methods', 'IMediaPlayerMethods', '', 'primitive', NULL, true, '—', 'components.media_controller.props.methods.description', 'Imperative methods from useMediaPlayer(). Provides play(), pause(), seek(), setVolume(), toggleMute(), setPlaybackRate(), requestRemotePlayback().', 1, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ae749d5d-181e-42c9-b3db-b1488fc80fc2', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', 'a74ac73e-c29d-47d0-8c34-9926c717bdac', 'inset', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.inset.description', 'YouTube-style overlay mode: the shell sits on top of the media surface with a dark gradient and auto-hides on visible=false. When false, renders as a regular always-on toolbar.', 2, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3ad7a5a5-486d-4956-94bb-7770c2d3b8b7', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', 'a74ac73e-c29d-47d0-8c34-9926c717bdac', 'visible', 'boolean', '', 'primitive', NULL, false, 'true', 'components.media_controller.props.visible.description', 'Visibility flag driven by the parent autohide logic. Only meaningful when inset=true. When false, the shell is opacity: 0 and pointer-events: none.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('eccf9904-4639-418f-969a-cd2621246bf5', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', 'a74ac73e-c29d-47d0-8c34-9926c717bdac', 'playbackRates', 'ReadonlyArray<number>', '', 'primitive', NULL, false, '[0.5, 0.75, 1, 1.25, 1.5, 2]', 'components.media_controller.props.playback_rates.description', 'Available playback rates exposed via the config cog menu. When the array has more than 1 entry, a "Playback speed" drill-down appears.', 4, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6f1c6bc9-cdc8-4354-bedf-768e954990fa', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', 'a74ac73e-c29d-47d0-8c34-9926c717bdac', 'allowRemotePlayback', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.allow_remote_playback.description', 'Enable the Cast / AirPlay button (Remote Playback API). The button only appears when this flag is true AND state.remoteAvailable is true at runtime.', 5, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('49bc13fa-1bc2-4612-90ee-1055a027b549', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', '81bf3198-8e79-40a4-8bb8-e1fcf0ae047c', 'style', 'string | Array<string> | object | StyleValue', NULL, NULL, NULL, false, NULL, NULL, NULL, 15, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4cfcb24c-fa4b-4df3-89e7-1ee24cce56e7', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', 'a74ac73e-c29d-47d0-8c34-9926c717bdac', 'downloadable', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.downloadable.description', 'Adds a "Download" row to the config cog menu when true. Requires downloadUrl to be set.', 6, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6ecc1235-1f72-4896-9b3e-724b8f95b37d', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', 'a74ac73e-c29d-47d0-8c34-9926c717bdac', 'downloadUrl', 'string | null', '', 'primitive', NULL, false, 'null', 'components.media_controller.props.download_url.description', 'URL surfaced to the consumer when the Download menu item is clicked. Supports same-origin, data: and blob: URLs natively; cross-origin URLs are routed through a fetch → blob pipeline.', 7, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b1f59b77-108c-47a2-b4a0-5f29bea9abca', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', 'a74ac73e-c29d-47d0-8c34-9926c717bdac', 'downloadFilename', 'string', '', 'primitive', NULL, false, 'undefined', 'components.media_controller.props.download_filename.description', 'Suggested filename for the downloaded file (<a download="…"> attribute).', 8, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4a374784-6797-4e7b-917c-5d3608be2784', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', 'a74ac73e-c29d-47d0-8c34-9926c717bdac', 'qualityOptions', 'ReadonlyArray<TQualityOption>', '', 'primitive', NULL, false, '[]', 'components.media_controller.props.quality_options.description', 'Optional list of quality variants. When ≥ 2 entries are present, a "Quality" drill-down appears in the config menu. Each entry is { quality: string; label: string }.', 9, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('df5a6859-cdad-4401-9983-1472d455a15a', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', 'a74ac73e-c29d-47d0-8c34-9926c717bdac', 'currentQuality', 'string | null', '', 'primitive', NULL, false, 'null', 'components.media_controller.props.current_quality.description', 'Currently-active quality identifier displayed as the appendText in the Quality menu row.', 10, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2778ee22-8ebb-4b9b-9318-5598648528e9', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', 'a74ac73e-c29d-47d0-8c34-9926c717bdac', 'showPrevious', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.show_previous.description', 'Show the "previous track" transport button. The parent listens to the previous emit and decides the action (skip back 10s or jump to the previous playlist track).', 11, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bb55bccc-5240-422b-a076-b24dfd80a993', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', 'a74ac73e-c29d-47d0-8c34-9926c717bdac', 'showNext', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.show_next.description', 'Show the "next track" transport button. The parent owns the action.', 12, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a79de4ba-9166-4b47-ade7-644f0c2b8b11', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', 'a74ac73e-c29d-47d0-8c34-9926c717bdac', 'showLoop', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.show_loop.description', 'Show the tri-state loop button (none → all → one → none). Supports v-model:loopMode.', 13, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ecd1a31f-510c-4f3c-b76a-e21f57d27874', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', 'a74ac73e-c29d-47d0-8c34-9926c717bdac', 'showShuffle', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.show_shuffle.description', 'Show the shuffle toggle button. Supports v-model:shuffle.', 14, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e48d7773-68b1-48b7-842a-e52b6b24f492', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', 'a74ac73e-c29d-47d0-8c34-9926c717bdac', 'loopMode', 'TAudioLoopMode', '', 'primitive', NULL, false, '''none''', 'components.media_controller.props.loop_mode.description', 'Current loop mode: "none" | "all" | "one". The Controller cycles on click and emits update:loopMode; the parent applies its playlist or <audio loop> policy.', 15, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e5a08034-67ee-4a42-968e-669a9dde4570', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', 'a74ac73e-c29d-47d0-8c34-9926c717bdac', 'shuffle', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.shuffle.description', 'Current shuffle state. The Controller toggles on click and emits update:shuffle; the parent switches its next-track resolution.', 16, false, NULL, NULL);
