INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('88025eca-be84-49a6-ad18-2175992f2888', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', '81bf3198-8e79-40a4-8bb8-e1fcf0ae047c', 'modelValue', 'number', '', 'primitive', NULL, true, '—', 'components.media_scrubber.props.model_value.description', 'Current value between min and max. Supports v-model. The component never mutates this directly — every change surfaces via update:modelValue.', 0, false, NULL, NULL);
