INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('019e4090-5509-4604-a781-93900d30307c', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', '81bf3198-8e79-40a4-8bb8-e1fcf0ae047c', 'max', 'number', '', 'primitive', NULL, true, '—', 'components.media_scrubber.props.max.description', 'Upper bound of the value range. Required to compute the thumb position. Passing 0 or any value <= min freezes the scrubber at the start.', 2, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('999e3b40-137b-4b77-9145-8e06a53a03aa', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', '81bf3198-8e79-40a4-8bb8-e1fcf0ae047c', 'step', 'number', '', 'primitive', NULL, false, '0', 'components.media_scrubber.props.step.description', 'Discrete step. 0 (default) means continuous — pointer events emit the raw float; positive values snap each emission to the nearest multiple.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9d88e113-a1ee-489a-8083-2f894f2fc921', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', '81bf3198-8e79-40a4-8bb8-e1fcf0ae047c', 'buffered', 'number', '', 'primitive', NULL, false, 'undefined', 'components.media_scrubber.props.buffered.description', 'Optional buffered position (end of the browser''s media buffer). Renders the __buffer bar from min up to buffered. Pass undefined to hide the bar entirely.', 4, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a81ee25d-2c29-4c14-98f3-10908a8269c7', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', '81bf3198-8e79-40a4-8bb8-e1fcf0ae047c', 'orientation', 'TMediaScrubberOrientation', '', 'primitive', NULL, false, '''horizontal''', 'components.media_scrubber.props.orientation.description', 'Layout axis. horizontal = YouTube timeline shape; vertical = volume / level meter shape (top of track = max, bottom = min).', 5, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7178c992-4711-4256-84c6-ad848f3b84eb', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', '81bf3198-8e79-40a4-8bb8-e1fcf0ae047c', 'disabled', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_scrubber.props.disabled.description', 'Disables pointer + keyboard interaction. The element drops out of the tab order (tabindex="-1") and pointer events become no-ops.', 6, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8c1a4e3a-5729-42e7-8abd-f53df9f5cc6b', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', '81bf3198-8e79-40a4-8bb8-e1fcf0ae047c', 'showThumbOnHoverOnly', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_scrubber.props.show_thumb_on_hover_only.description', 'Hides the thumb at rest and reveals it on hover / focus / drag — the YouTube pattern. When false, the thumb is always visible.', 7, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a4692449-f568-44ae-b9c1-3ea3c13fcf59', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:53.94968+00', '81bf3198-8e79-40a4-8bb8-e1fcf0ae047c', 'showHoverTooltip', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_scrubber.props.show_hover_tooltip.description', 'Shows a tooltip above the cursor (horizontal only) reflecting the hovered value. Content can be overridden via the #tooltip slot.', 8, false, NULL, NULL);
