INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1a44b5a6-722b-4138-9483-c9d4ad58e793', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '34735d03-4f8f-49cc-912f-58cc5703411f', 'isSomeSelected', '(items: IDataTableSelectableItem | IDataTableSelectableItem[]) => boolean', '', 'Returns true when at least one item in the argument list is selected.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f6422958-6707-4b15-bd8d-da01c84c1dfc', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '34735d03-4f8f-49cc-912f-58cc5703411f', 'select', '(items: IDataTableSelectableItem[], value: boolean) => void', '', 'Set the selection state of the given items to value. Delegates to the active selectStrategy (single, page, or all).', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('118c90a3-6929-466d-9802-56a7c64de9e3', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '34735d03-4f8f-49cc-912f-58cc5703411f', 'toggleSelect', '(item: IDataTableSelectableItem) => void', '', 'Toggle the selection state of a single item.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('37324cdc-dd0f-4339-93f7-043f38166616', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '34735d03-4f8f-49cc-912f-58cc5703411f', 'selectAll', '(value: boolean) => void', '', 'Select or deselect all eligible items according to the active strategy. Strategy page selects only the current page; strategy all selects across all pages.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1ee5beb8-a89a-4d1c-a82b-de68403f5380', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '34735d03-4f8f-49cc-912f-58cc5703411f', 'someSelected', 'ComputedRef<boolean>', '', 'True when the selected Set is non-empty. Used to render the indeterminate state on the select-all checkbox.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c47582d6-02b4-4996-bd8d-e5beade1cfcb', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '34735d03-4f8f-49cc-912f-58cc5703411f', 'allSelected', 'ComputedRef<boolean>', '', 'True when all eligible items (non-disabled) are selected according to the active strategy.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ebde6331-63a8-41e4-80bb-f80b17df8ca7', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '34735d03-4f8f-49cc-912f-58cc5703411f', 'showSelectAll', 'ComputedRef<boolean>', '', 'Whether the select-all checkbox should be visible. Always false for the single select strategy.', 7, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c0412d14-b514-4fcf-b0ad-869018f569fc', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '59a412a2-d07e-4c0a-ad54-daacfed88728', 'currentSnap', 'Ref<TSheetSnapId>', '', 'The id of the currently active snap point. Writable — programmatically call snapTo() or assign directly. Kept in sync with options.defaultSnap via a watcher.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('61a6d13f-8a50-4bd5-8df0-f0f79d411f7b', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '59a412a2-d07e-4c0a-ad54-daacfed88728', 'dragOffset', 'ShallowRef<number>', '', 'Live pixel offset from the baseline snap height during an active drag. Positive = sheet growing (finger moving up). Resets to 0 on pointer release. Bind to a CSS translateY to achieve 1:1 finger tracking.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1696caf2-68e8-48a5-84d2-4551ee0abb0a', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '59a412a2-d07e-4c0a-ad54-daacfed88728', 'isDragging', 'ShallowRef<boolean>', '', 'True while a pointer is captured by the handle. Use it to suppress the sheet transition (transition: none) so the user sees immediate 1:1 tracking instead of the animated snap.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c8e03404-727c-4893-8389-54ab0784ba56', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '59a412a2-d07e-4c0a-ad54-daacfed88728', 'snapTo', '(id: TSheetSnapId) => void', '', 'Programmatically move to a named snap point. Respects the persistent constraint (cannot snap to closed when persistent=true). Resets dragOffset to 0.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('60ea9909-c9c8-4c51-947c-6739bf8cb5c6', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '59a412a2-d07e-4c0a-ad54-daacfed88728', 'dismiss', '() => void', '', 'Convenience wrapper for snapTo("closed"). Blocked when persistent=true (falls back to the lowest non-zero snap).', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9f7eb50e-d140-4b67-84a4-f9ce08e0dfb0', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '59a412a2-d07e-4c0a-ad54-daacfed88728', 'currentSnapHeight', 'ComputedRef<number>', '', 'Resolved pixel height of the current snap point. SSR-safe (returns 0 when window is absent). Used to compute the sheet height style: currentSnapHeight + dragOffset.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('dd93f0d0-d454-405d-b923-d180452e35bb', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '9e553650-4330-4dae-b8a0-ab826a339697', 'sizeClasses', 'ComputedRef<string[]>', '', 'Component-local BEM modifier class (e.g. "origam-btn--size-small") plus the typographic utility class (e.g. "origam--text-sm") bridging the legacy to modern taxonomy.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5a1d48a0-1c85-4539-b729-c88aaff9b6cc', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '9e553650-4330-4dae-b8a0-ab826a339697', 'sizeStyles', 'ComputedRef<string[]>', '', 'Inline width and height declarations for custom numeric or CSS-length sizes (when the value is not a named preset).', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('901da229-8087-4e11-9533-76b20e94a0b1', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'efd67f4a-2a94-44b9-915a-15f0619e1218', 'min', 'ComputedRef<number>', '', 'Parsed minimum value. Defaults to 0 when props.min is undefined or null.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e3aeaed7-759e-4410-8992-f9632b023845', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'efd67f4a-2a94-44b9-915a-15f0619e1218', 'max', 'ComputedRef<number>', '', 'Parsed maximum value. Defaults to 100 when props.max is undefined or null.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1decc793-2c2b-451b-bb1c-7ba98a5e0f32', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'efd67f4a-2a94-44b9-915a-15f0619e1218', 'step', 'ComputedRef<number>', '', 'Parsed step value. 0 means no stepping (any value between min and max is valid). Positive values define the snap grid.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4579157d-41b7-4030-a951-4ca5cdfc2c54', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'efd67f4a-2a94-44b9-915a-15f0619e1218', 'decimals', 'ComputedRef<number>', '', 'Number of decimal places to preserve in roundValue output. Derived from max(getDecimals(step), getDecimals(min)) to match the precision implied by the step grid.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9d6c7fda-432f-471e-b996-75e24931dd79', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'efd67f4a-2a94-44b9-915a-15f0619e1218', 'roundValue', '(value: string | number) => number', '', 'Snap a raw value to the nearest valid step, clamped to [min, max]. Handles the min-offset edge case so that a step=5 min=3 grid snaps to 3, 8, 13, … rather than 0, 5, 10, ….', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6715e998-e7fd-4602-a183-e199313671c3', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '3c9573ff-184e-47b9-8d46-715cd26965b5', 'time', 'ShallowRef<number>', '', 'Remaining milliseconds. Starts at the initial milliseconds value, decrements on each tick, and bottoms out at 0. Bind to a progress bar width to visualise the countdown.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f10d23b6-6a32-4eeb-8497-d72d4f90c573', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '3c9573ff-184e-47b9-8d46-715cd26965b5', 'clear', '() => void', '', 'Stops the interval without resetting time. Use to pause the countdown (e.g. while the user is hovering the snackbar).', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9cadeb56-4cad-46ff-af94-697020852309', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '3c9573ff-184e-47b9-8d46-715cd26965b5', 'reset', '() => void', '', 'Clears the interval and resets time to the initial milliseconds value on the next tick. Use when the snackbar content changes and the countdown should restart.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8c3e7239-6484-41a5-9031-faec0d5e4554', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '3c9573ff-184e-47b9-8d46-715cd26965b5', 'start', '(el?: HTMLElement) => void', '', 'Start (or resume) the countdown. Reads the CSS transitionDuration of el to synchronise tick frequency with the progress bar animation. Falls back to 200 ms when no element is provided or no transition is set. Clears any existing interval before starting.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('76ba69db-6d5a-4c6a-b877-d9164de4a6de', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '650ee29b-d5bd-4ebe-ab7f-59dc9b16d262', 'items', 'Readonly<Ref<ReadonlyArray<ISnackbarGroupItem>>>', '', 'Reactive read-only snapshot of the current stack. Mutate only through notify / dismiss / dismissAll — direct writes are blocked at the TypeScript level.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d1b55fae-d056-4706-9350-59b020a060c8', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '650ee29b-d5bd-4ebe-ab7f-59dc9b16d262', 'notify', '(opts: ISnackbarGroupItemOptions) => string', '', 'Push a new item onto the stack. Accepts ISnackbarGroupItemOptions (message, variant, icon, duration, onDismiss callback…). Returns the generated item id so the caller can dismiss it early.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('20b8e2c9-3a8c-4825-90f5-eaf449241af7', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '650ee29b-d5bd-4ebe-ab7f-59dc9b16d262', 'dismiss', '(itemId: string) => void', '', 'Remove the item with the given id from the stack, cancel its auto-dismiss timer, and invoke its onDismiss callback if any.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('65bc17e0-b2d5-4e9b-9443-2230e270f169', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '650ee29b-d5bd-4ebe-ab7f-59dc9b16d262', 'dismissAll', '() => void', '', 'Dismiss every item in the stack in one call. Iterates a snapshot of the ids so mid-loop mutations are safe.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d3038bbd-db4f-475c-a872-a661ce84493d', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '26059c27-9335-448e-a83f-466f2c74e4c6', 'sortBy', 'Ref<Array<IDataTableSortItem>>', '', 'Reactive array of active sort descriptors, each with a key (column key) and an order (asc | desc). Driven by useVModel against the host table props.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('506ca4db-aa29-471c-a93b-7391914d89ba', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '26059c27-9335-448e-a83f-466f2c74e4c6', 'toggleSort', '(column: IInternalDataTableHeader) => void', '', 'Cycle the sort state for a column: none → asc → desc → none (or asc when mustSort=true). Respects multiSort — when false, replaces the entire sortBy array with a single entry.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9065647d-25dc-4033-b16a-e3f0e8abcf68', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '26059c27-9335-448e-a83f-466f2c74e4c6', 'isSorted', '(column: IInternalDataTableHeader) => boolean', '', 'Returns true when the column has an active sort entry in sortBy. Used by header cells to show the sort icon.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('20f8fb04-d266-4e38-b512-c012a20df140', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '70c5573d-90e2-4790-9e73-629632f2cae9', 'ssrBootStyles', 'ComputedRef<CSSProperties | []>', '', 'An object `{ transition: "none !important" }` when the component has not yet booted, or an empty array after the first animation frame. Spread onto the root element via :style to suppress hydration-flash transitions.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2cef9731-0cda-47d3-b2d7-1e31fc48af4b', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '70c5573d-90e2-4790-9e73-629632f2cae9', 'isBooted', 'Readonly<ShallowRef<boolean>>', '', 'False on the server and during the first rAF after mount, true thereafter. Useful as a guard before running DOM-dependent logic that assumes the component is fully hydrated.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b14658d1-875a-4b8c-b4a6-620b152144a5', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'd7fa47b4-60e3-4753-bdae-cad6cdabb484', NULL, 'number', 'utils.detail.apc_acontrast.returns', 'Signed APCA contrast value. Absolute value >= 45 is the recommended minimum for body text.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3106bc9e-c980-4ebd-a30f-9c60fca1f18e', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '37c11900-85bf-4968-951f-7beadd5a35af', 'globalTop', 'Readonly<ShallowRef<boolean>>', '', 'True when this component is the last entry in GLOBAL_STACK (topmost overlay on the page). Updated asynchronously via setTimeout to avoid synchronous circular reads during stack registration.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('421dc238-6dc0-44ab-bf5d-cb78bdd9de76', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '37c11900-85bf-4968-951f-7beadd5a35af', 'localTop', 'ComputedRef<boolean>', '', 'True when this overlay has no active child overlays (nothing opened on top of it within its own sub-tree). Used to decide whether clicks on the backdrop should close this overlay.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ad09b7ed-8190-45d2-82c7-1e42fe7a8e9a', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '37c11900-85bf-4968-951f-7beadd5a35af', 'stackStyles', 'ComputedRef<{ zIndex: number }>', '', 'Style object containing the computed zIndex. Spread onto the overlay root element so it automatically rises above the previous topmost overlay.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e73fcd6d-ed01-4549-a5c1-0044a5941f09', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '9e146d0f-e06e-481c-b25c-6c3578883845', 'colorClasses / colorStyles', 'ComputedRef<string[]>', '', 'Tokenised intent values emit a utility class (origam--bg-primary); custom CSS colors emit an inline style. Both are empty when disabled/hover/active is true (state-inline path takes over).', 0, false, NULL, NULL);
