INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f46a53f8-80ad-4392-8598-9f6409d45216', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '9e146d0f-e06e-481c-b25c-6c3578883845', 'paddingClasses / paddingStyles', 'ComputedRef<string[]>', '', 'Delegated to usePadding via a reactive getter proxy to preserve dependency tracking across state swaps.', 4, false, NULL, NULL);
