INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('51c32b6a-8476-4176-8c3d-94c7c368980f', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '9e146d0f-e06e-481c-b25c-6c3578883845', 'gapClasses / gapStyles', 'ComputedRef<string[]>', '', 'Gap has no dedicated composable. Emits an inline style (gap: Npx or gap: <value>) when a gap override is present. gapClasses is always empty.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3201cc3d-eba0-433e-ad54-e23153bde7ee', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '59022107-17d3-4dfb-9b88-065f1e3a75d1', 'icon', 'ComputedRef<string | undefined>', '', 'Resolved center/replace icon. Returns the status icon when statusIconPosition="replace" and no explicit props.icon was provided, otherwise passes through props.icon.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('81958c83-bd59-4ee5-8e72-8958c532a013', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '59022107-17d3-4dfb-9b88-065f1e3a75d1', 'prependIcon', 'ComputedRef<string | undefined>', '', 'Resolved prepend-slot icon. Injects the status icon when statusIconPosition is prepend or both and props.prependIcon is unset.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b1c96938-42ea-41a5-9505-1a3ae45c4da9', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '59022107-17d3-4dfb-9b88-065f1e3a75d1', 'appendIcon', 'ComputedRef<string | undefined>', '', 'Resolved append-slot icon. Injects the status icon when statusIconPosition is append or both and props.appendIcon is unset.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c214df22-c8ed-4c7e-a401-024c91383c24', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '59022107-17d3-4dfb-9b88-065f1e3a75d1', 'statusClasses', 'ComputedRef<string[]>', '', 'Array containing `{name}--{status}` when a status is set, empty otherwise. Bind to the root element for SCSS state selectors.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3dd734ef-5d0c-4331-970f-e27eacff08d1', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '59022107-17d3-4dfb-9b88-065f1e3a75d1', 'statusIntent', 'ComputedRef<TColor | undefined>', '', 'The resolved TColor intent for the current status (success→success, info→info, warning→warning, error→danger). Undefined when no status is set. Consumed by useStateEffect to force the semantic surface color.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b08a392b-ed34-4330-b2c3-b1ce5c9644e4', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'c2ba38b1-e12b-40ce-a7dd-9bf516bc2d95', 'isStuck', 'ShallowRef<boolean | "top" | "bottom">', '', 'Current stuck state. "top" = anchored at the top of the viewport (sidebar shorter than viewport or scrolled to top), "bottom" = anchored at the bottom edge, true = stuck mid-page (sidebar taller than viewport, user scrolled past the top edge), false = not sticky (isSticky prop is false).', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('94b8cb83-e04b-4984-85f8-10670d0a0a5e', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'c2ba38b1-e12b-40ce-a7dd-9bf516bc2d95', 'stickyStyles', 'ComputedRef<Array<CSSProperties | undefined>>', '', 'Two-element style array to spread on the element. The first resets top/bottom/height when isSticky is enabled. The second applies the computed positional offset: the layoutItem top when not yet stuck, or the scrolled stuckPosition when stuck mid-page or at the bottom.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1dd36078-408e-4581-a179-f161d4ffc1fc', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '13315667-b8ee-409c-9d5e-d91b46634d15', 'id', 'ComputedRef<string>', '', 'The element id used as the CSS scope selector (#id). Apply this id to the root element of the component so the injected styles target only this instance.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d21610c5-429c-4d1a-9e40-8d5a335992a7', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '13315667-b8ee-409c-9d5e-d91b46634d15', 'css', 'ShallowRef<string>', '', 'The current generated CSS string. Reactive — updates whenever the styles ComputedRef changes.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7f25a591-4a23-4eb0-b605-a33ec951367b', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '13315667-b8ee-409c-9d5e-d91b46634d15', 'load / unload', '() => void', '', 'Manually control style tag injection. Normally called automatically on mount / scope dispose. Call load() to re-inject after an explicit unload().', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('25b5e871-157d-4244-8cf1-073697a35951', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '13315667-b8ee-409c-9d5e-d91b46634d15', 'isLoaded', 'Readonly<ShallowRef<boolean>>', '', 'True when the <style> tag is currently present in document.head.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ddb4783d-5ede-4e6e-b9c3-ca7b53f1ce40', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '34c60917-db99-4488-aa1f-2c507b50e466', 'teleportTarget', 'ComputedRef<Element | undefined>', '', 'The resolved .origam-overlay-container element inside the target, or undefined when teleport is disabled (target=true) or the app is running on the server (SSR). Pass directly to <Teleport :to="teleportTarget">.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('94509859-9530-466f-975e-120444860d7a', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '409063cf-6f33-4ea0-a49e-8acf1d2cb586', 'hostRef', 'Ref<HTMLElement | undefined>', '', 'Template ref to assign to the contenteditable element. The composable uses it to read and write innerHTML, attach the selectionchange listener, and focus the element before applying a format command.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('edb505db-4d50-44d6-98d0-7b9a1c034e5e', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '409063cf-6f33-4ea0-a49e-8acf1d2cb586', 'active', 'ITextareaRichActiveState', '', 'Reactive object tracking the formatting state at the current caret position. Properties: bold, italic, underline, code, link (booleans), listBullet, listOrdered (booleans), heading (0 | 1 | 2 | 3). Bind to toolbar button :active props.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6797f2d1-f5c4-4161-9daa-6eb1ffa01848', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '409063cf-6f33-4ea0-a49e-8acf1d2cb586', 'format', '(command: TTextareaToolbarCommand, value?: string) => void', '', 'Apply a formatting command. Delegates to document.execCommand for bold, italic, underline, lists, and headings. Handles link creation (value = URL) and inline code toggling (insertHTML). Calls onFormat and onUpdate after every change.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f94584f0-a573-46fa-8198-d77fd173fd13', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '409063cf-6f33-4ea0-a49e-8acf1d2cb586', 'isFormatActive', '(command: TTextareaToolbarCommand) => boolean', '', 'Returns whether the given command is active at the current caret position. Reads from the reactive active object — a convenience wrapper for toolbar binding.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9fc88d4f-0aa0-4a6f-828b-2282df286e13', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '409063cf-6f33-4ea0-a49e-8acf1d2cb586', 'setValue', '(html: string) => void', '', 'Imperatively update the contenteditable innerHTML with sanitised HTML. No-ops when hostRef is unset or when the content is already identical (avoids cursor jump).', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('85b37d57-0877-4f44-a197-116ccbfe9251', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '409063cf-6f33-4ea0-a49e-8acf1d2cb586', 'onInput / onKeydown / onPaste', '(event) => void', '', 'Event handlers to bind on the host element. onInput emits sanitised HTML. onKeydown intercepts Cmd/Ctrl+B/I/U/E/K and Cmd+Shift+7/8 for list shortcuts. onPaste strips HTML to sanitised form (or escapes plain text) before inserting.', 5, false, NULL, NULL);
