INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d3b200a7-5a66-4d9c-82bf-d44c3852d06d', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '653b99ed-d240-4185-9d40-eeb066fd14aa', 'theme', 'Readonly<Ref<TTheme>>', '', 'The current brand theme value: ''auto'' | ''light'' | ''dark'' | string (custom brand). Read-only reactive ref.', 0, false, NULL, NULL);
