INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('31614805-6f7f-496a-8b6d-0dac7f5a3b23', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '41f1f9b5-931e-41c5-8252-4ffe4a501496', 'addMovement', '(e: TouchEvent) => void', '', 'Record a touchstart or touchmove event sample. Each touch point is tracked independently. Call this on every touchmove to build a time-stamped sample history.', 0, false, NULL, NULL);
