INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('abb114db-5e39-459b-ac20-4be26e9a0fe2', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'fb770e5e-9cc1-416a-8cde-cce8e34b0b35', 'videoRef', 'Ref<HTMLVideoElement | null>', '', 'Template ref to bind to the `<video>` element. Reused from `options.videoRef` when provided.', 0, false, NULL, NULL);
