INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('28d01983-63ba-4a5a-a88e-dd4b7f70af03', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'd2386caa-a644-4e8b-8c6b-46d46b94efe3', 'containerRef', 'Ref<HTMLElement | undefined>', '', 'Assign to the scrollable container element. The composable reads `scrollTop` from it and listens to `handleScroll` / `handleScrollend`.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('996fd1e9-c427-4b8e-8cd5-000f7cb4a11b', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'd2386caa-a644-4e8b-8c6b-46d46b94efe3', 'markerRef', 'Ref<HTMLElement | undefined>', '', 'Assign to a zero-height element at the top of the list content area. Its `offsetTop` is used to compute an offset if there is padding or a header above the virtual list.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('60b35b83-ea39-4582-9b9e-93a1ef3124e6', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'd2386caa-a644-4e8b-8c6b-46d46b94efe3', 'computedItems', 'ComputedRef<Array<{ raw: T; index: number }>>', '', 'The slice of items currently in the render window. Each entry carries the original `raw` item and its absolute `index` in the full list.', 2, false, NULL, NULL);
