INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8f89d3af-2182-4d37-84af-b837e1365052', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'd2386caa-a644-4e8b-8c6b-46d46b94efe3', 'scrollToIndex', '(index: number, options?: Partial<IGoToOptions>) => void', '', 'Programmatically scroll the container to a specific item index. Defers the scroll if the list has not yet measured (first render not complete). Pass `{ duration: 0 }` for instant scroll.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a61c4e6d-8a1f-4e0e-8ea8-2ec184e5e9ba', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'd2386caa-a644-4e8b-8c6b-46d46b94efe3', 'handleScroll', '() => void', '', 'Bind to the `scroll` event of the container element. Computes scroll velocity and triggers visible-items recalculation.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fce1186e-1f3b-4ca2-89fa-8ec7c6d570ea', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'd2386caa-a644-4e8b-8c6b-46d46b94efe3', 'handleScrollend', '() => void', '', 'Bind to the `scrollend` event. Resets scroll velocity and recalculates the visible window.', 7, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d0146a1b-9fa1-4a8f-9228-498dde2d2e1a', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', 'd2386caa-a644-4e8b-8c6b-46d46b94efe3', 'handleItemResize', '(index: number, height: number) => void', '', 'Call when a rendered item changes its measured height. Updates the size cache and triggers an offset recalculation. Wire via a ResizeObserver on each rendered row.', 8, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b5f3e394-e266-4c7c-873d-4154e608c69b', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '2589bf3e-1f68-43aa-98d6-75fa7c7c7771', '(model)', 'Ref<TInnerVal<Inner>> & { readonly externalValue: Props[Prop] }', '', 'A writable computed ref. Reading it returns the current value (controlled or internal). Writing it updates the internal ref and emits `update:prop`. The `externalValue` accessor returns the raw prop value without transformIn applied.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('85ceaa1a-0aa6-4286-93eb-66d9387da2bd', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '69863aa2-1c82-4927-86c7-5beac820d1de', 'patternUrl', 'ComputedRef<string>', '', 'CSS `url("data:image/svg+xml,…")` string. Bind to `background-image` on any container element, or pass to `install()`. Recomputes reactively when options change.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b8e66ae1-b5c5-41ee-a30e-ec4f8b3838a4', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '69863aa2-1c82-4927-86c7-5beac820d1de', 'install', '(target?: HTMLElement) => HTMLElement | null', '', 'Inject a full-cover `<div>` layer with `position: absolute; inset: 0` and the pattern as background-image into `target` (defaults to document.body). Sets `position: relative` on the target if it is `static`. Returns the created layer element, or null during SSR.', 1, false, NULL, NULL);
