INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('efdf50f9-3944-4bdb-942f-0d171db44006', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '927cd65a-3324-44d6-b382-e090dde9b2f7', 'list', 'types.detail.file_field_display.list', 'Default. Renders each selected file as a card in a vertical stack below the field. Suitable when filenames and per-file actions (remove, download, progress) need to be visible.', 0, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c1f6ea91-61cc-4b18-ac0d-c89e7bab3ed0', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '927cd65a-3324-44d6-b382-e090dde9b2f7', 'chips', 'types.detail.file_field_display.chips', 'Renders each selected file as a closable <OrigamChip> inline inside the field. Compact mode — best for forms where many files can be selected but vertical space is limited.', 1, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('72c7bec6-a055-4cf0-a032-5af0d52be53a', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '927cd65a-3324-44d6-b382-e090dde9b2f7', 'counter', 'types.detail.file_field_display.counter', 'Shows a single "N files selected" line with an <OrigamCounter>. Most compact mode — use when the file names are irrelevant to the user after selection.', 2, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('44d05e18-96a4-43d0-ac4f-b7002af299fd', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '5e6cfe38-30d9-4800-b444-3c9725cabfcf', 'false', 'types.detail.file_size.false', 'File sizes are not displayed. This is the default behaviour when the showSize prop is omitted.', 0, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d82a5c44-c31c-4dcc-a7f1-e1588e7a8cab', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '5e6cfe38-30d9-4800-b444-3c9725cabfcf', 'true', 'types.detail.file_size.true', 'File sizes are displayed using the SI divisor (1 000) — KB, MB, GB.', 1, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fc8f50e6-781d-4ce8-ba56-2484eecbbb6d', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '5e6cfe38-30d9-4800-b444-3c9725cabfcf', '1000', 'types.detail.file_size.1000', 'Explicit SI (decimal) units: 1 KB = 1 000 bytes, 1 MB = 1 000 000 bytes. Matches the marketing convention used by most storage providers.', 2, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7d190471-a475-4eac-80d3-06f9d1999e60', '2026-11-28 08:34:23.934078+00', '2026-11-28 08:34:23.934078+00', '5e6cfe38-30d9-4800-b444-3c9725cabfcf', '1024', 'types.detail.file_size.1024', 'Binary / IEC units: 1 KiB = 1 024 bytes, 1 MiB = 1 048 576 bytes. Traditional computing convention; more accurate for OS-reported file sizes.', 3, false, NULL, NULL);
